        'toc': 'Tabla de contenido',
        'title': 'Título',
        'cover': 'Cubierta',
        'notes': 'Notas',
    },
}

def book_lang_code(lang):
    if not lang:
        return 'en'
    l = str(lang).strip()
    # reference seems to take first part before -_ and lowercase?
    # fr-FR worked as fr. FR for runtime didn't, but book?
    base = l.replace('_','-').split('-')[0]
    return base.lower()

def loc_book(lang, key):
    code = book_lang_code(lang)
    d = BOOK_LOC.get(code) or BOOK_LOC['en']
    return d.get(key, BOOK_LOC['en'].get(key, key))

# Runtime messages: only fr specially translated for some library error strings.
# We store templates with placeholders; filled in errors module where needed.
RUNTIME_FR = {
    'error_converting_bookoption': "Erreur en convertissant l'option de livre :",
    # Many others filled later as discovered
}

def is_fr_runtime(runtime_lang):
    return bool(runtime_lang) and str(runtime_lang).startswith('fr')

