    code = book_lang_code(lang)
    return {
        'en': 'english',
        'fr': 'french',
        'de': 'german',
        'es': 'spanish',
        'it': 'italian',
        'pt': 'portuguese',
        'nl': 'dutch',
        'ru': 'russian',
    }.get(code, 'english')
