    # path like "templates/html.css" or "data/help.txt"
    # 1) filesystem relative to this file (dev mode)
    try:
        base = os.path.dirname(os.path.abspath(__file__))
        full = os.path.join(base, path)
        if os.path.isfile(full):
            with open(full, 'rb') as f:
                return f.read()
    except Exception:
        pass
    # 2) zipapp: sys.argv[0] is the zip file
    try:
        zpath = sys.argv[0]
        if zpath and zipfile.is_zipfile(zpath):
            with zipfile.ZipFile(zpath) as z:
                return z.read(path)
    except Exception:
        pass
    # 3) relative to executable location / src
    try:
        exe_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
        for cand in [os.path.join(exe_dir, 'src', path), os.path.join(exe_dir, path)]:
            if os.path.isfile(cand):
                with open(cand,'rb') as f: return f.read()
    except Exception:
        pass
    raise FileNotFoundError(path)
