import sys, os, datetime

class CrowLogger:
    def __init__(self, verbose=False, quiet=False, no_fancy=False, force_emoji=False, runtime_lang='en'):
        self.verbose = verbose
        self.quiet = quiet
        self.no_fancy = no_fancy
        self.force_emoji = force_emoji
        self.runtime_lang = runtime_lang
        self.records = []  # (level, target, msg) for fancy summary (warn/error)
        # emoji determination
        self.emoji = False
        if force_emoji:
            self.emoji = True
        elif sys.stderr.isatty():
            lang_env = os.environ.get('LANG','') or ''
            if 'utf-8' in lang_env.lower():
                self.emoji = True
        self.fancy = (not no_fancy) and (not verbose) and (not quiet)
        # In fancy mode with tty, reference shows progress bars; we don't reproduce animation.
        # Treat tty fancy similarly for final messages.
    def header(self):
        if self.quiet:
            return
        if self.emoji:
            sys.stderr.write("🐦 CROWBOOK 📚 0.17.0\n")
        else:
            sys.stderr.write("CROWBOOK 0.17.0\n")
        try: sys.stderr.flush()
        except Exception: pass
    # levels: ERROR, WARN, INFO, DEBUG
    def log(self, level, msg, target="crowbook::book"):
        if self.verbose:
            t = datetime.datetime.now().strftime("%H:%M:%S")
            # Some debug messages in reference include thread id "(1)"
            if level == 'DEBUG':
                sys.stderr.write(f"{t} [DEBUG] (1) {target}: {msg}\n")
            else:
                sys.stderr.write(f"{t} [{level}] {target}: {msg}\n")
            return
        if self.quiet:
            if level == 'ERROR':
                sys.stderr.write(f"[ERROR] {msg}\n")
            return
        if self.no_fancy:
            if level in ('ERROR','WARN','INFO'):
                sys.stderr.write(f"[{level}] {msg}\n")
            return
        # fancy: collect warn/error
        if level in ('WARN','ERROR'):
            self.records.append((level,msg))
        # info/debug suppressed (would be progress bars on tty)
    def error(self, msg, target="crowbook::book"):
        self.log('ERROR', msg, target)
    def warn(self, msg, target="crowbook::book"):
        self.log('WARN', msg, target)
    def info(self, msg, target="crowbook::book"):
        self.log('INFO', msg, target)
    def debug(self, msg, target="crowbook::book"):
        self.log('DEBUG', msg, target)
    def print_fancy_summary(self):
        if not self.fancy:
            return
        if not self.records:
            return
        warn_icon = "⚠️ " if self.emoji else ""
        sys.stderr.write(f"{warn_icon}WARNING Crowbook exited successfully, but the following errors occurred:\n")
        for level,msg in self.records:
            if level=='WARN':
                icon = "⚠️ " if self.emoji else ""
                sys.stderr.write(f"{icon}WARNING {msg}\n")
            else:
                icon = "💣 " if self.emoji else ""
                sys.stderr.write(f"{icon}ERROR {msg}\n")
    # Top-level plain error (never emoji bomb, even if force emoji, but if no_fancy? still plain)
    def plain_error(self, msg):
        # msg may already end without newline; reference adds newline, sometimes msg contains trailing \n\n handled by caller suffix
        sys.stderr.write(f"ERROR {msg}\n")
    def fancy_error(self, msg):
        # Used by some call sites: if fancy (not no_fancy and not verbose?) emoji bomb only if emoji.
        # In -n mode, plain. In -v mode, plain (observed). In -q mode, bomb if emoji (fancy_error still used).
        if self.no_fancy or self.verbose:
            sys.stderr.write(f"ERROR {msg}\n")
        else:
            icon = "💣 " if self.emoji else ""
            sys.stderr.write(f"{icon}ERROR {msg}\n")

# global
LOG = CrowLogger()
def set_logger(l):
    global LOG
    LOG = l
    return l
