import re

class YamlError(Exception):
    def __init__(self, msg, line=1, col=1):
        self.msg=msg; self.line=line; self.col=col
        super().__init__(self.display())
    def display(self):
        return f"{self.msg} at line {self.line} column {self.col}"

class Y:
    __slots__=('tag','value','raw','line','col')
    def __init__(self,tag,value,raw=None,line=1,col=1):
        self.tag=tag; self.value=value; self.raw=raw if raw is not None else value; self.line=line; self.col=col
    def __repr__(self): return yaml_debug(self)

def rust_escape(s):
    out=[]
    for ch in str(s):
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        else: out.append(ch)
    return ''.join(out)

def yaml_debug(v):
    if not isinstance(v,Y):
        return repr(v)
    if v.tag=='String': return f'String("{rust_escape(v.value)}")'
    if v.tag=='Integer': return f'Integer({v.value})'
    if v.tag=='Real': return f'Real("{rust_escape(v.raw)}")'
    if v.tag=='Boolean': return f'Boolean({"true" if v.value else "false"})'
    if v.tag=='Null': return 'Null'
    if v.tag=='Array': return 'Array(['+', '.join(yaml_debug(x) for x in v.value)+'])'
    if v.tag=='Hash': return 'Hash({'+', '.join(f'{yaml_debug(k)}: {yaml_debug(val)}' for k,val in v.value)+'})'
    return f'{v.tag}({v.value!r})'

def scalar_to_yaml(raw,line=1,col=1,style='plain'):
    raw_stripped = raw.strip()
    if style!='plain':
        return Y('String', raw, raw, line,col)
    if raw_stripped in ('~','null'):
        return Y('Null', None, raw_stripped,line,col)
    if raw_stripped=='true': return Y('Boolean',True,raw_stripped,line,col)
    if raw_stripped=='false': return Y('Boolean',False,raw_stripped,line,col)
    # ints
    s=raw_stripped
    try:
        if re.fullmatch(r'[-+]?[0-9]+',s):
            return Y('Integer',int(s,10),s,line,col)
        if re.fullmatch(r'0x[0-9a-fA-F]+',s):
            return Y('Integer',int(s,16),s,line,col)
        if re.fullmatch(r'0o[0-7]+',s):
            return Y('Integer',int(s[2:],8),s,line,col)
        # yaml-rust also maybe leading 0 octal? Observed 010 accepted as int (maybe 8 or 10, unclear) -- use decimal? 
        # Test later if needed
    except Exception:
        pass
    # real
    if re.fullmatch(r'[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?',s) and (('.' in s) or ('e' in s.lower())):
        return Y('Real',s,s,line,col)
    if s in ('.inf','-.inf','+.inf','.nan','.Inf','.INF','-.Inf'):
        return Y('Real',s,s,line,col)
    return Y('String', raw_stripped, raw_stripped,line,col)

class Parser:
    def __init__(self,text):
        self.text=text
        self.lines=text.splitlines()
        self.anchors={}
    def parse(self):
        # Remove document markers at boundaries? Keep simple: strip leading --- line and trailing ...
        # But caller often handles.
        lines=self.lines
        # find first non-empty/comment line
        idx=0
        # create logical lines with numbered original (1-based)
        self.ll=[]
        for i,raw in enumerate(lines, start=1):
            self.ll.append((i,raw))
        val, nxt = self.parse_block(0, min_indent=0)
        # check leftover non-empty
        for j in range(nxt, len(self.ll)):
            ln,raw=self.ll[j]
            if raw.strip()=='' or raw.strip().startswith('#') or raw.strip() in ('---','...'):
                continue
            # stray content -> mimic yaml error roughly
            if raw.lstrip().startswith('*'):
                raise YamlError('while scanning an anchor or alias, did not find expected alphabetic or numeric character', ln, 1)
            raise YamlError('while parsing a block mapping, did not find expected key', ln, 1)
        if val is None:
            return Y('Null',None,'',1,1)
        return val
    def strip_comment(self,s):
        # remove " #..." outside quotes/brackets (simple)
        in_s=False; in_d=False; esc=False; depth=0
        for i,ch in enumerate(s):
            if esc: esc=False; continue
            if in_d and ch=='\\': esc=True; continue
            if ch=="'" and not in_d: in_s=not in_s
            elif ch=='"' and not in_s: in_d=not in_d
            elif not in_s and not in_d:
                if ch in '[{': depth+=1
                elif ch in ']}': depth=max(0,depth-1)
                elif ch=='#' and depth==0 and (i==0 or s[i-1].isspace()):
                    return s[:i].rstrip()
        return s
    def indent_of(self,raw):
        n=0
        for ch in raw:
            if ch==' ': n+=1
            elif ch=='\t': n+=1
            else: break
        return n
    def skip_empty(self,idx):
        while idx < len(self.ll):
            ln,raw=self.ll[idx]
            if raw.strip()=='' or raw.strip().startswith('#') or raw.strip() in ('---','...'):
                idx+=1; continue
            break
        return idx
    def parse_block(self,idx,min_indent=0):
        idx=self.skip_empty(idx)
        if idx>=len(self.ll): return None, idx
        ln,raw=self.ll[idx]
        if raw.lstrip().startswith('*') and (len(raw.lstrip())==1 or raw.lstrip()[1].isspace()):
            raise YamlError('while scanning an anchor or alias, did not find expected alphabetic or numeric character', ln, 1)
        ind=self.indent_of(raw)
        if ind < min_indent:
            return None, idx
        stripped=raw.strip()
        # sequence?
        if stripped=='-' or stripped.startswith('- '):
            return self.parse_sequence(idx, ind)
        # mapping detection: a key colon at this indent in first line (or ?)
        if self.find_mapping_colon(self.strip_comment(raw[ind:])) is not None or stripped.startswith('? ') or stripped==':' or stripped.startswith(': '):
            return self.parse_mapping(idx, ind)
        # scalar (maybe multiline plain continuing)
        # Could be flow on its own
        val, consumed = self.parse_value_token(idx, raw[ind:], ind)
        return val, consumed
    def find_mapping_colon(self,s):
        # return index of ": " or trailing ":" outside quotes/flow, for plain keys
        in_s=False; in_d=False; esc=False; depth=0
        for i,ch in enumerate(s):
            if esc: esc=False; continue
            if in_d and ch=='\\': esc=True; continue
            if ch=="'" and not in_d: in_s=not in_s
            elif ch=='"' and not in_s: in_d=not in_d
            elif not in_s and not in_d:
                if ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch==':' and depth==0:
                    if i+1>=len(s) or s[i+1].isspace():
                        return i
        return None
    def parse_mapping(self,idx,indent):
        entries=[]
        start_line=self.ll[idx][0] if idx < len(self.ll) else 1
        while True:
            idx=self.skip_empty(idx)
            if idx>=len(self.ll): break
            ln,raw=self.ll[idx]
            ind=self.indent_of(raw)
            if ind<indent: break
            if ind>indent:
                # should have been consumed as nested; break to caller?
                break
            content=self.strip_comment(raw[ind:])
            if content.strip()=='':
                idx+=1; continue
            if content.lstrip().startswith('*') and (len(content.lstrip())==1 or content.lstrip()[1].isspace()):
                raise YamlError('while scanning an anchor or alias, did not find expected alphabetic or numeric character', ln, 1)
            # complex ? key
            if content.startswith('? '):
                key_str=content[2:].strip()
                key=self.parse_scalar_token(key_str,ln,ind+3)
                idx+=1
                # optional : value on next line?
                # value is Null if next is next key
                # Simplified: check next line starting with ':'
                nidx=self.skip_empty(idx)
                if nidx < len(self.ll) and self.ll[nidx][1].strip().startswith(':'):
                    # parse inline after colon
                    nln,nraw=self.ll[nidx]; nind=self.indent_of(nraw); after=nraw[nind+1:].strip()
                    if after:
                        val, idx = self.parse_value_token(nidx, nraw[nind+1:].lstrip(), indent)
                    else:
                        v, idx2 = self.parse_block(nidx+1, indent+1)
                        val=v if v is not None else Y('Null',None,'',ln,1); idx=idx2
                else:
                    val=Y('Null',None,'', self.ll[nidx][0] if nidx < len(self.ll) else ln+1,1)
                entries.append((key,val)); continue
            colon=self.find_mapping_colon(content)
            if colon is None:
                # stray line within mapping
                if content.startswith('*'):
                    raise YamlError('while scanning an anchor or alias, did not find expected alphabetic or numeric character', ln, 1)
                raise YamlError('while parsing a block mapping, did not find expected key', ln, ind+1)
            key_raw=content[:colon].strip()
            if key_raw=='':
                key=Y('Null',None,'',ln,ind+1)
            else:
                key=self.parse_scalar_token(key_raw,ln,ind+1)
            after=content[colon+1:]
            # after may begin with space
            after_stripped=after.strip()
            if after_stripped=='':
                # nested value on following indented lines, or null
                nidx=self.skip_empty(idx+1)
                if nidx < len(self.ll):
                    nln,nraw=self.ll[nidx]; nind=self.indent_of(nraw)
                    if nind>indent:
                        val, idx = self.parse_block(nidx, nind)
                        if val is None: val=Y('Null',None,'',nln,1)
