import re

class YamlError(Exception):
    def __init__(self, msg, line=1, col=1):
        self.msg=msg; self.line=line; self.col=col
        super().__init__(self.display())
    def display(self):
        return f"{self.msg} at line {self.line} column {self.col}"

class Y:
    __slots__=('tag','value','raw','line','col')
    def __init__(self,tag,value,raw=None,line=1,col=1):
        self.tag=tag; self.value=value; self.raw=raw if raw is not None else value; self.line=line; self.col=col
    def __repr__(self): return yaml_debug(self)

def rust_escape(s):
    out=[]
    for ch in str(s):
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        else: out.append(ch)
    return ''.join(out)

def yaml_debug(v):
    if not isinstance(v,Y):
        return repr(v)
    if v.tag=='String': return f'String("{rust_escape(v.value)}")'
    if v.tag=='Integer': return f'Integer({v.value})'
    if v.tag=='Real': return f'Real("{rust_escape(v.raw)}")'
    if v.tag=='Boolean': return f'Boolean({"true" if v.value else "false"})'
    if v.tag=='Null': return 'Null'
    if v.tag=='Array': return 'Array(['+', '.join(yaml_debug(x) for x in v.value)+'])'
    if v.tag=='Hash': return 'Hash({'+', '.join(f'{yaml_debug(k)}: {yaml_debug(val)}' for k,val in v.value)+'})'
    return f'{v.tag}({v.value!r})'

def scalar_to_yaml(raw,line=1,col=1,style='plain'):
    raw_stripped = raw.strip()
    if style!='plain':
        return Y('String', raw, raw, line,col)
    if raw_stripped in ('~','null'):
        return Y('Null', None, raw_stripped,line,col)
    if raw_stripped=='true': return Y('Boolean',True,raw_stripped,line,col)
    if raw_stripped=='false': return Y('Boolean',False,raw_stripped,line,col)
    # ints
    s=raw_stripped
    try:
        if re.fullmatch(r'[-+]?[0-9]+',s):
            return Y('Integer',int(s,10),s,line,col)
        if re.fullmatch(r'0x[0-9a-fA-F]+',s):
            return Y('Integer',int(s,16),s,line,col)
        if re.fullmatch(r'0o[0-7]+',s):
            return Y('Integer',int(s[2:],8),s,line,col)
        # yaml-rust also maybe leading 0 octal? Observed 010 accepted as int (maybe 8 or 10, unclear) -- use decimal? 
        # Test later if needed
    except Exception:
        pass
    # real
    if re.fullmatch(r'[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?',s) and (('.' in s) or ('e' in s.lower())):
        return Y('Real',s,s,line,col)
    if s in ('.inf','-.inf','+.inf','.nan','.Inf','.INF','-.Inf'):
        return Y('Real',s,s,line,col)
    return Y('String', raw_stripped, raw_stripped,line,col)

