def parse_yaml(text):
    return Parser(text).parse()

def yaml_to_python(v):
    if not isinstance(v,Y): return v
    if v.tag in ('String','Real'): return v.value if v.tag=='String' else v.raw
    if v.tag=='Integer': return v.value
    if v.tag=='Boolean': return v.value
    if v.tag=='Null': return None
    if v.tag=='Array': return [yaml_to_python(x) for x in v.value]
    if v.tag=='Hash': return {yaml_to_python(k): yaml_to_python(val) for k,val in v.value}
    return v.value
