import sys, os
from resources import load_text

HELP_TEMPLATE=None

def bin_name():
    a=sys.argv[0] if sys.argv else 'executable'
    return os.path.basename(a) or 'executable'

def help_text():
    txt=load_text('data/help.txt')
    # first (?) only usage contains executable; replace token 'executable' in usage line
    b=bin_name()
    if b!='executable':
        txt=txt.replace('    executable [OPTIONS] [BOOK]', f'    {b} [OPTIONS] [BOOK]')
    return txt

VERSION_TEXT='crowbook 0.17.0\n'

