                    l=lines[i]
                    qm=re.match(r'^ {0,3}>[ \t]?(.*)$',l)
                    if qm:
                        qlines.append(qm.group(1)); i+=1; continue
                    if l.strip()=='':
                        # if next is quote, include blank
                        j=i
                        while j < len(lines) and lines[j].strip()=='':
                            j+=1
                        if j < len(lines) and re.match(r'^ {0,3}>',lines[j]):
                            qlines.append(''); i+=1; continue
                        break
                    # lazy continuation: if qlines last nonblank and l is plain text and not other block start
                    if qlines and qlines[-1].strip()!='' and not self.is_block_start(lines,i,allow_para=True):
                        qlines.append(l); i+=1; continue
                    break
                inner=self.parse_blocks(qlines)
                blocks.append(N('blockquote',inner))
                continue
            # Table check
            if i+1 < len(lines) and '|' in line and self.is_table_delim(lines[i+1]):
                table, i = self.parse_table(lines,i)
                if table:
                    blocks.append(table); continue
            # List
            if self.match_list_item(line) is not None:
                lst, i = self.parse_list(lines,i)
                blocks.append(lst); continue
            # Definition list check: look ahead for ': ' within next few lines before blank
            dl=self.try_parse_deflist(lines,i)
            if dl:
                node,i = dl; blocks.append(node); continue
            # Indented code (not after blank handling? At block start)
            if line.startswith('    ') or line.startswith('\t'):
                code_lines=[]
                while i < len(lines):
                    l=lines[i]
                    if l.startswith('    '):
                        code_lines.append(l[4:]); i+=1
                    elif l.startswith('\t'):
                        code_lines.append(l[1:]); i+=1
                    elif l.strip()=='':
                        # include if next indented
                        j=i
                        while j < len(lines) and lines[j].strip()=='':
                            j+=1
                        if j < len(lines) and (lines[j].startswith('    ') or lines[j].startswith('\t')):
                            code_lines.append(''); i+=1
                        else:
                            break
                    else:
                        break
                while code_lines and code_lines[-1]=='':
                    code_lines.pop()
                text='\n'.join(code_lines)+'\n' if code_lines else ''
                blocks.append(N('codeblock',text=text,lang=''))
                continue
            # Paragraph / Setext
            para_lines=[]; setext_level=None
            while i < len(lines):
                l=lines[i]
                if l.strip()=='':
                    break
                if para_lines:
                    # setext underline?
                    if re.match(r'^ {0,3}=+[ \t]*$',l):
                        setext_level=1; i+=1; break
                    if re.match(r'^ {0,3}-+[ \t]*$',l):
                        setext_level=2; i+=1; break
                    # interruption by other blocks
                    if self.is_block_start(lines,i):
                        break
                    # table start interruption (header line is current para? handled if l has | and next delim were already check ???)
                    if '|' in l and i+1 < len(lines) and self.is_table_delim(lines[i+1]):
                        break
                else:
                    # first line: if it's a ref def already consumed above, not here
                    pass
                para_lines.append(l); i+=1
                # if next line is table delim and para is single line and contains |, it will be handled as setext check loop: delimiter contains --- but with pipes not setext; break to table parse?
                if i < len(lines) and para_lines and len(para_lines)==1 and '|' in para_lines[0] and self.is_table_delim(lines[i]):
                    # rewind one to let table parser handle header
                    i-=1; para_lines=[]
                    table,i=self.parse_table(lines,i)
                    if table: blocks.append(table)
                    break
            if setext_level is not None:
                content='\n'.join([pl.strip() for pl in para_lines])
                blocks.append(N('heading',self.parse_inlines(content),level=setext_level))
            elif para_lines:
                # If paragraph lines include reference defs at start, strip them (already prescanned)
                # Remove leading ref def lines
                # Our try_consume at block start would have removed, so fine
                text='\n'.join(para_lines)
                blocks.append(N('para',self.parse_inlines(text)))
            # if para_lines empty due to table, loop continues
        return blocks
    def prescan_refs(self,lines):
        # Extract link reference definitions anywhere not in fenced code (approximation)
        in_fence=False; fence_char=None; fence_count=0
        i=0
        while i < len(lines):
            l=lines[i]
            fc=self.match_fence(l) if not in_fence else None
            if in_fence:
                if self.match_fence_close(l,fence_char,fence_count): in_fence=False
                i+=1; continue
            if fc:
                in_fence=True; fence_char=fc[1]; fence_count=fc[2]; i+=1; continue
            m=re.match(r'^ {0,3}\[([^\]]+)\]:[ \t]*(\S.*)?$',l)
            if m and not m.group(1).startswith('^'):
                label=m.group(1); rest=m.group(2) or ''
                # parse dest/title possibly next line title
                dest,title,consumed=self.parse_ref_dest(rest,lines,i)
                if dest is not None:
                    self.refs[normalize_label(label)]=(dest,title)
            i+=1
    def parse_ref_dest(self,rest,lines,idx):
        rest=rest.strip()
        if not rest:
            # dest may be on next line
            if idx+1 < len(lines) and lines[idx+1].strip():
                rest=lines[idx+1].strip()
            else:
                return None,None,0
        # dest angle or bare
        dest=None; title=None; remaining=''
        if rest.startswith('<'):
            end=rest.find('>')
            if end==-1: return None,None,0
            dest=rest[1:end]; remaining=rest[end+1:].strip()
        else:
            parts=rest.split(None,1)
            dest=parts[0]; remaining=parts[1].strip() if len(parts)>1 else ''
        if remaining:
            title=self.parse_title_token(remaining)
            if title is None and remaining not in ('','\n'):
                # invalid ref def if leftover gibberish? Pulldown may still accept if title on next line; ignore
                pass
        return dest,title,0
    def parse_title_token(self,s):
        s=s.strip()
        if len(s)>=2 and ((s[0]=='"' and s[-1]=='"') or (s[0]=="'" and s[-1]=="'") or (s[0]=='(' and s[-1]==')')):
            inner=s[1:-1]
            return inner.replace('\\"', '"').replace("\\'", "'")
        return None
    def try_consume_ref_defs(self,lines,i):
        # If line is a link reference definition, consume 1 or 2 lines (title next line) and return new index; else None
        l=lines[i]
        m=re.match(r'^ {0,3}\[([^\]]+)\]:[ \t]*(.*)$',l)
        if not m or m.group(1).startswith('^'):
            return None
        rest=m.group(2).strip()
        # ensure this is valid reference: dest present either rest or next line, and no extra text after title on same lines.
        # Use prescanned ref presence and syntactic check
        label=normalize_label(m.group(1))
        if label not in self.refs:
            return None
        # verify rest is plausible: starts with < or non-space and not huge paragraph?
        # Consume line; if rest empty and next line is dest, consume it; if title on following line alone, consume.
        j=i+1
        # if rest empty, next line must be consumed as dest
        if rest=='' and j < len(lines):
            j+=1
        # title on next line if next line is purely a title token
        if j < len(lines):
            nxt=lines[j].strip()
            if self.parse_title_token(nxt) is not None:
                j+=1
        # Also if rest contains only dest and title inline, fine one line.
        # But if a normal paragraph line like "[foo]: bar baz qux" with extra words isn't a ref? parse_title_token of remainder returns None; prescan would have still stored (our prescan permissive). Check rigorous:
        if rest:
            # split dest /title
            if rest.startswith('<'):
                end=rest.find('>')
                if end==-1: return None
                rem=rest[end+1:].strip()
            else:
                parts=rest.split(None,1); rem=parts[1].strip() if len(parts)>1 else ''
            if rem and self.parse_title_token(rem) is None:
                return None
        return j
    def match_fence(self,line):
        m=re.match(r'^( {0,3})(`{3,}|~{3,})(.*)$',line)
        if not m: return None
        indent=len(m.group(1)); seq=m.group(2); info=m.group(3)
        if seq[0]=='`' and '`' in info: return None
        return (indent,seq[0],len(seq),info)
    def match_fence_close(self,line,char,count):
        m=re.match(r'^ {0,3}('+re.escape(char)+r'{3,})[ \t]*$',line)
        return bool(m and len(m.group(1))>=count)
    def is_thematic(self,line):
        s=line.strip()
        if len(s)<3: return False
        # remove spaces/tabs
        t=s.replace(' ','').replace('\t','')
        return len(t)>=3 and all(c==t[0] for c in t) and t[0] in '-_*'
    def is_html_block_start(self,line):
        s=line.lstrip(' ')
        indent=len(line)-len(s)
        if indent>3: return False
        if s.startswith('<!--') or s.startswith('<?') or s.startswith('<!'):
            return True
        m=re.match(r'^</?([A-Za-z][A-Za-z0-9-]*)(?:[ \t/>]|$)',s)
        if not m: return False
        tag=m.group(1).lower()
        if tag in BLOCK_TAGS:
            return True
        # condition 7: complete open/close tag alone on line
        if re.match(r'^</?[A-Za-z][^>]*>[ \t]*$',s):
            return True
        return False
    def is_block_start(self,lines,i,allow_para=False):
        l=lines[i]
        if re.match(r'^ {0,3}(#{1,6})(?:[ \t]+|[ \t]*$)',l): return True
        if self.match_fence(l): return True
        if re.match(r'^ {0,3}>',l): return True
        if self.is_thematic(l): return True
        if self.is_html_block_start(l): return True
        # list interruption: bullet always, ordered only if start 1 for para interruption in CommonMark - but at quote lazy check allow_para uses too
        lm=self.match_list_item(l)
        if lm:
            ordered,start,_,_,_=lm
            if not ordered: return True
            if start==1: return True
            if allow_para: return True
        return False
    def match_list_item(self,line):
        m=re.match(r'^( {0,3})([-+*])([ \t]+|$)(.*)$',line)
        if m:
            indent=len(m.group(1)); marker=m.group(2); spaces=m.group(3); rest=m.group(4)
            # thematic ----- could look list? "- -" etc not; if line thematic break caller precedence before list for '---' etc. Bullet content cannot be thematic? - *
            return (False,None,indent, marker, rest)
        m=re.match(r'^( {0,3})([0-9]{1,9})([.)])([ \t]+|$)(.*)$',line)
        if m:
            indent=len(m.group(1)); return (True,int(m.group(2)),indent, m.group(2)+m.group(3), m.group(5))
        return None
    def parse_list(self,lines,i):
        first=self.match_list_item(lines[i])
        ordered,start,base_indent,marker,rest = first
        items=[]
        tight=True
        # marker kind: bullet char or delimiter type for continuing same list
        def same_list(m):
            if not m: return False
            o,s,ind,mark,r=m
            if o!=ordered: return False
            if ind!=base_indent: return False
            if not ordered and mark!=marker: return False
            if ordered:
                # delimiter . vs ) must match
                return mark[-1]==marker[-1]
            return True
        while i < len(lines):
            m=self.match_list_item(lines[i])
            if not same_list(m):
                break
            o,s,ind,mark,r=m
            line=lines[i]
            # content indent calculate
            # find position of content in line
            # marker start ind, marker len
            content_start=None
            # regex positions
            if not ordered:
                mm=re.match(r'^( {0,3})([-+*])([ \t]+|$)',line)
                sp_len=len(mm.group(3)) if mm.group(3) else 1
                # if spaces >=5 or content empty (?) content indent = ind+ markerlen+1
                if sp_len>=5 or r.strip()=='':
                    content_indent=ind+len(mark)+1
                else:
                    content_indent=ind+len(mark)+sp_len
                first_content=line[content_indent:] if len(line)>=content_indent else ''
            else:
                mm=re.match(r'^( {0,3})([0-9]{1,9}[.)])([ \t]+|$)',line)
                sp_len=len(mm.group(3)) if mm.group(3) else 1
                if sp_len>=5 or r.strip()=='':
                    content_indent=ind+len(mark)+1
                else:
                    content_indent=ind+len(mark)+sp_len
                first_content=line[content_indent:] if len(line)>=content_indent else ''
            item_lines=[first_content]
            i+=1
            while i < len(lines):
                l=lines[i]
                if l.strip()=='':
                    # look ahead
                    j=i
                    while j < len(lines) and lines[j].strip()=='':
                        j+=1
                    if j>=len(lines):
                        i=j; break
                    # if next is new same list item at base indent, end item
                    if same_list(self.match_list_item(lines[j])):
                        i=j; break
                    # if next indented >= content_indent, include blanks
                    nxt_indent=len(lines[j])-len(lines[j].lstrip(' '))
                    # tab handling approx
                    if lines[j].startswith('\t'): nxt_indent=4
                    if nxt_indent>=content_indent:
                        for _ in range(i,j): item_lines.append('')
                        i=j; tight=False; continue
                    # blank separates list from following block -> end
                    i=j; break
                # new item?
                if same_list(self.match_list_item(l)):
                    break
                # indented content
                if l.startswith('\t'):
                    item_lines.append(l[1:] if content_indent<=4 else l[1:]); i+=1; continue
                cur_indent=len(l)-len(l.lstrip(' '))
                if cur_indent>=content_indent:
                    item_lines.append(l[content_indent:]); i+=1; continue
                # lazy continuation if last line nonblank and not a block start at base?
                if item_lines and item_lines[-1].strip()!='' and not self.is_block_start(lines,i,allow_para=True):
                    item_lines.append(l); i+=1; continue
                break
            # trim trailing blank lines in item_lines
            while item_lines and item_lines[-1].strip()=='':
                item_lines.pop()
            task=None
            if item_lines:
                tm=re.match(r'^\[( |x|X)\][ \t]+(.*)$',item_lines[0])
                if tm:
                    task=(tm.group(1).lower()=='x')
                    item_lines[0]=tm.group(2)
            item_blocks=self.parse_blocks(item_lines) if item_lines else []
            items.append(N('item',item_blocks,task=task))
        return N('list',items,ordered=ordered,start=(start if ordered else None),tight=tight), i
    def is_table_delim(self,line):
        s=line.strip()
        if '|' not in s and '-' not in s: return False
        # split cells
        cells=self.split_table_row(s)
        if not cells: return False
        for c in cells:
            if not re.fullmatch(r':?-+:?',c.strip()):
                return False
        return True
    def split_table_row(self,line):
        s=line.strip()
        # remove outer pipes if present (not escaped)
        if s.startswith('|'):
            s=s[1:]
        if s.endswith('|') and not s.endswith('\\|'):
            s=s[:-1]
        cells=[]; cur=''; i=0; in_code=0
        while i < len(s):
            ch=s[i]
            if ch=='\\' and i+1 < len(s) and s[i+1]=='|':
                cur+='|'; i+=2; continue
            if ch=='`':
                # count backticks
                j=i
                while j < len(s) and s[j]=='`': j+=1
                n=j-i; cur+=s[i:j]; i=j
                # find closing - simplistic keep in_code toggle
                continue
            if ch=='|':
                cells.append(cur); cur=''; i+=1; continue
            cur+=ch; i+=1
        cells.append(cur)
        return cells
    def parse_table(self,lines,i):
        header_cells=self.split_table_row(lines[i])
        delim_cells=self.split_table_row(lines[i+1])
        if len(header_cells)!=len(delim_cells):
            return None,i
        aligns=[]
        for c in delim_cells:
            c=c.strip()
            if c.startswith(':') and c.endswith(':'): aligns.append('center')
            elif c.endswith(':'): aligns.append('right')
            elif c.startswith(':'): aligns.append('left')
            else: aligns.append(None)
        headers=[self.parse_inlines(c.strip()) for c in header_cells]
        i+=2; rows=[]
        while i < len(lines) and lines[i].strip()!='':
            if '|' not in lines[i]:
                # Rows without pipe maybe end table? GFM row could be without? treat as end
                break
            cells=self.split_table_row(lines[i])
            # pad/truncate
            if len(cells)<len(headers): cells+=['']*(len(headers)-len(cells))
            cells=cells[:len(headers)]
            rows.append([self.parse_inlines(c.strip()) for c in cells]); i+=1
        return N('table',headers=headers,aligns=aligns,rows=rows), i
    def try_parse_deflist(self,lines,i):
        # term lines are para lines until a line starting with ':' ; there must be at least one term line
        # Scan up to blank/next block for /^ {0,3}: /
        j=i
        term_lines=[]
        found=False
        while j < len(lines) and lines[j].strip()!='':
            if re.match(r'^ {0,3}:[ \t]+',lines[j]) or re.match(r'^ {0,3}:[ \t]*$',lines[j]):
                found=True; break
            if self.is_block_start(lines,j) and j>i:
                return None
            term_lines.append(lines[j]); j+=1
        if not found or not term_lines:
            return None
        # Parse def list sequence
        items=[] # list of (term inlines, list definitions blocks)
        idx=i
        while idx < len(lines):
            # term(s): collect until a definition line or blank
            tlines=[]
            while idx < len(lines) and lines[idx].strip()!='' and not re.match(r'^ {0,3}:[ \t]',lines[idx]):
                tlines.append(lines[idx]); idx+=1
            if not tlines:
                break
            # Could be multiple terms if multiple lines? pulldown treats each line? For simplicity each line separate term sharing following definitions? Observed single.
            # Collect definitions
            defs=[]
            while idx < len(lines):
                m=re.match(r'^( {0,3}):([ \t]+)(.*)$',lines[idx])
                if not m: break
                content_indent=len(m.group(1))+1+len(m.group(2))
                if len(m.group(2))>=5: content_indent=len(m.group(1))+2
                first=lines[idx][content_indent:] if len(lines[idx])>=content_indent else m.group(3)
                dlines=[first]; idx+=1
                while idx < len(lines):
                    l=lines[idx]
                    if l.strip()=='':
                        # look ahead to indented content or next def/term break
                        j2=idx
                        while j2 < len(lines) and lines[j2].strip()=='':
                            j2+=1
                        if j2 < len(lines) and (len(lines[j2])-len(lines[j2].lstrip(' '))>=content_indent):
                            dlines.append(''); idx+=1; continue
                        idx=j2; break
                    cur_ind=len(l)-len(l.lstrip(' '))
                    if cur_ind>=content_indent:
                        dlines.append(l[content_indent:]); idx+=1; continue
                    break
                defs.append(self.parse_blocks(dlines))
                # skip blank already handled? if next is blank skip in outer
                # if next line is a new term (not definition), outer loop will process
                # But if blank line separates terms, outer expects we skip blanks between items
                save=idx
                while idx < len(lines) and lines[idx].strip()=='':
                    idx+=1
                # if no more def for this term, proceed; blanks skipped for next term (pulldown list continues)
                if idx < len(lines) and re.match(r'^ {0,3}:[ \t]',lines[idx]):
                    continue
                break
            for tl in tlines:
                items.append((self.parse_inlines(tl.strip()), defs))
            # if next lines don't look like a term+def, stop; peek ahead: if next nonblank lacks following def, end list without consuming it.
            # We already consumed blank lines in def loop; check ahead quickly
            if idx>=len(lines): break
            # look for a def within next para lines
            peek=idx; has=False
            while peek < len(lines) and lines[peek].strip()!='':
                if re.match(r'^ {0,3}:[ \t]',lines[peek]): has=True; break
                peek+=1
            if not has: break
        return N('deflist',items=items), idx
    # ------------- inline parsing
    def parse_inlines(self,text):
        return self._parse_inline(text)
    def _find_closing_bracket(self,s,start):
        # start at '[' index; return index of matching ']'
        depth=0; i=start; in_code=None
        while i < len(s):
            ch=s[i]
            if ch=='\\' and i+1 < len(s):
                i+=2; continue
            if ch=='`':
                j=i
                while j < len(s) and s[j]=='`': j+=1
                ticks=s[i:j]
                end=s.find(ticks,j)
                if end!=-1:
                    i=end+len(ticks); continue
                i=j; continue
            if ch=='[':
                depth+=1
            elif ch==']':
                depth-=1
                if depth==0:
                    return i
            i+=1
        return -1
    def _parse_dest_title(self,s,i):
        # s[i]=='(' ; parse until matching ')', return (dest,title,nextindex) or None
        assert s[i]=='('
        j=i+1
        # skip whitespace including newlines
        while j < len(s) and s[j].isspace(): j+=1
        if j>=len(s): return None
        dest=''
        title=None
        if j < len(s) and s[j]=='<':
            end=j+1
            while end < len(s) and s[end] not in ('>','\n'):
                if s[end]=='\\' and end+1 < len(s): end+=1
                end+=1
            if end>=len(s) or s[end]!='>': return None
            dest=s[j+1:end]; j=end+1
        else:
            start=j; depth=0
            while j < len(s):
                ch=s[j]
                if ch=='\\' and j+1 < len(s): j+=2; continue
                if ch.isspace(): break
                if ch=='(':
                    depth+=1
                elif ch==')':
                    if depth==0: break
                    depth-=1
                j+=1
            dest=s[start:j]
            dest=re.sub(r'\\([()])',r'\1',dest)
        while j < len(s) and s[j].isspace(): j+=1
        if j < len(s) and s[j] in ('"',"'",'('):
            opener=s[j]; closer={ '"':'"',"'":"'",'(':')'}[opener]; j+=1; start=j
            while j < len(s) and s[j]!=closer:
                if s[j]=='\\' and j+1 < len(s): j+=1
                j+=1
            if j>=len(s): return None
            title=s[start:j]; title=title.replace('\\"', '"').replace("\\'", "'"); j+=1
            while j < len(s) and s[j].isspace(): j+=1
        if j < len(s) and s[j]==')':
            return dest,title,j+1
        return None
    def _parse_link_at(self,s,i,is_image=False):
        # i points to '[' (for image '[' is after '!')
        close=self._find_closing_bracket(s,i)
        if close==-1: return None
        text=s[i+1:close]
        j=close+1
        dest=None; title=None; nexti=None
        if j < len(s) and s[j]=='(':
            parsed=self._parse_dest_title(s,j)
            if not parsed: return None
            dest,title,nexti=parsed
        elif j < len(s) and s[j]=='[':
            end=self._find_closing_bracket(s,j)
            if end==-1: return None
            label=s[j+1:end] or text
            key=normalize_label(label)
            # footnote-like? no
            if key not in self.refs: return None
            dest,title=self.refs[key]; nexti=end+1
        else:
            # shortcut ref
            key=normalize_label(text)
            if key not in self.refs:
                return None
            dest,title=self.refs[key]; nexti=j
        children=self._parse_inline(text)
        if is_image:
            return N('image',children,dest=dest,title=title),nexti
        else:
            return N('link',children,dest=dest,title=title),nexti
    def _parse_inline(self,s):
        nodes=[]; buf=[]
        def flush():
            if buf:
