def plain_text(inlines):
    out=[]
    for n in inlines:
        if n.kind=='text': out.append(n.text)
        elif n.kind=='code': out.append(n.text)
        elif n.kind in ('emph','strong','strike','sup','sub','link'): out.append(plain_text(n.children))
        elif n.kind=='image': out.append(plain_text(n.children))
        elif n.kind=='softbreak': out.append(' ')
        elif n.kind=='hardbreak': out.append('\n')
        elif n.kind=='html': out.append(n.text)
        elif n.kind=='footnoteref': out.append('')
    return ''.join(out)
