import os, sys, re
from pathlib import PurePosixPath
from errors import CrowError, could_not_parse_book
from logger import LOG
from options import Options, SPECS
from yamlmini import parse_yaml, YamlError, Y, yaml_debug
from mdparse import MdParser, N, plain_text
from cleaner import clean_text
import loc as locmod

class PanicError(Exception):
    def __init__(self,location,msg):
        super().__init__(msg); self.location=location; self.msg=msg

def join_display(parent, child):
    if child is None: return parent or ''
    child=str(child)
    if os.path.isabs(child) or not parent:
        return child
    return os.path.join(parent, child)

def parent_display(path):
    if path is None: return ''
    # os.path.dirname('b.book')='', dirname('./b.book')='.', dirname('/x/b')='/x'
    return os.path.dirname(str(path))

def read_source_bytes(path_display):
    """return bytes or raise CrowError specific to book config reading"""
    try:
        with open(path_display,'rb') as f: return f.read()
    except IsADirectoryError:
        raise CrowError("Error parsing configuration file: could not read source: Is a directory (os error 21)")
    except OSError as e:
        raise CrowError(f"Error parsing configuration file: could not read source: {e.strerror} (os error {e.errno})")

def decode_utf8_config(data):
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError:
        raise CrowError("Error parsing configuration file: could not read source: stream did not contain valid UTF-8")

def roman(n):
    try: n=int(n)
    except: return str(n)
    if n<=0:
        return str(n)
    vals=[(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    out=[]
    for v,s in vals:
        while n>=v:
            out.append(s); n-=v
    return ''.join(out)

class Element:
    def __init__(self,kind,**kw):
        self.kind=kind; self.__dict__.update(kw)

class Book:
    def __init__(self):
        self.options=None
        self.elements=[]
        self.source_arg=None
        self.source_file=None  # display or None for stdin/single
        self.parent_display=''
        self.single=False
        self.runtime_lang='en'
        self.set_error=None  # (key,value,msg)
        self.cli_pairs_success=[]
        self.filename_for_output=None  # stem-ish source arg basename without extension for auto outputs
    # ---- construction
    @classmethod
    def load(cls, book_arg, single=False, cli_pairs=None, autograph_text=None, runtime_lang='en', import_stack=None):
        book=cls()
        book.single=single; book.runtime_lang=runtime_lang; book.source_arg=book_arg
        book.options=Options(runtime_lang=runtime_lang)
        # CLI pairs initial
        cli_pairs=cli_pairs or []
        for key,val in cli_pairs:
            err=book.options.set_from_string(key,val,layer='cli')
            if err:
                LOG.error(f"Error initializing book: could not set {key} to {val}: {book.options.error_prefix_converting()}{err}", target="crowbook::book")
                book.set_error=(key,val,err)
                break
            else:
                book.cli_pairs_success.append((key,val))
        if autograph_text:
            # stored as initial normal value (config may override)
            if autograph_text.strip()!='':
                book.options.values['autograph']=autograph_text
                book.options.present.add('autograph')
        if single:
            book._load_single(book_arg, import_stack)
        else:
            book._load_book_file(book_arg, import_stack)
        # reapply successful CLI pairs for warning side-effects (aliases) - using a dummy options
        if book.cli_pairs_success:
            dummy=Options(runtime_lang=runtime_lang)
            # copy current cli? just conversion again
            for key,val in book.cli_pairs_success:
                dummy.set_from_string(key,val,layer='cli')
        if book.set_error:
            key,val,err=book.set_error
            src=""
            if book.options.source_file:
                src=f"{book.options.source_file}:{book.options.source_line}: "
            raise CrowError(f"Error in setting key {key}: {src}{book.options.error_prefix_converting()}{err}")
        book._postprocess()
        return book
    def _source_name_for_output(self,arg):
        if arg=='-':
            return None
        base=os.path.basename(str(arg))
        # remove last extension
        if '.' in base:
            return base[:base.rfind('.')] or base
        return base
    def _load_single(self,arg,import_stack):
        if arg=='-':
            data=sys.stdin.buffer.read()
            try:
                text=data.decode('utf-8')
            except UnicodeDecodeError:
                raise CrowError(f"-: Error parsing markdown: file - contains invalid UTF-8")
            self.source_file=None; self.parent_display=''; display='-'
            self.options.source_file=None; self.options.source_line=1
            self.filename_for_output=None
        else:
            if not os.path.exists(arg):
                raise CrowError(f"Could not find file '{arg}' for book")
            try:
                with open(arg,'rb') as f: data=f.read()
            except OSError:
                # reference maps read error to invalid UTF-8 message for chapters
                raise CrowError(f"{arg}: Error parsing markdown: file {os.path.basename(str(arg))} contains invalid UTF-8")
            try:
                text=data.decode('utf-8')
            except UnicodeDecodeError:
                raise CrowError(f"{arg}: Error parsing markdown: file {os.path.basename(str(arg))} contains invalid UTF-8")
            self.source_file=None  # options source is None in single mode
            self.parent_display=parent_display(arg)
            display=str(arg)
            self.options.source_file=None; self.options.source_line=1
            self.filename_for_output=self._source_name_for_output(arg)
        # one element numbered
        elem=self._make_file_element(display_path=display, entry_name=display, text=text, entry_type='numbered', explicit=None, shift=0, force_yaml=True, entry_line=None)
        self.elements.append(elem)
    def _load_book_file(self,arg,import_stack):
        import_stack=import_stack or []
        if arg=='-':
            data=sys.stdin.buffer.read()
            text=decode_utf8_config(data)
            self.source_file=None; self.parent_display=''; self.filename_for_output=None
        else:
            if not os.path.exists(arg):
                raise CrowError(f"Could not find file '{arg}' for book")
            data=read_source_bytes(arg)
            text=decode_utf8_config(data)
            self.source_file=str(arg); self.parent_display=parent_display(arg)
            self.filename_for_output=self._source_name_for_output(arg)
        self.options.source_file=self.source_file
        lines=text.splitlines()
        # Segment YAML
        yaml_lines=[]; i=0
        while i < len(lines):
            line=lines[i]
            if line and (line[0] in '+-!@' or line[0].isdigit()):
                break
            yaml_lines.append(line); i+=1
        self.options.source_line=len(yaml_lines) if yaml_lines else 1
