                    else:
                        b.numbered=False
                # plain title cache
                b.plain_title=plain_text(b.children)
        # part plain titles
        for elem in self.elements:
            if elem.kind=='part':
                if elem.title_inlines is not None: elem.plain_title=plain_text(elem.title_inlines)
                elif elem.title_blocks:
                    # concatenate block plain texts
                    elem.plain_title=' '.join(plain_text(b.children) if b.kind in ('para','heading') else '' for b in elem.title_blocks).strip()
                else: elem.plain_title=''
    # Metadata parsing helpers
    def metadata_inlines(self,key):
        raw=self.options.get_str(key,'')
        if raw=='':
            return []
        parser=MdParser(superscript=self.options.get_bool('crowbook.markdown.superscript',False),html_as_text=self.options.get_bool('crowbook.html_as_text',True))
        inls=parser.parse_inlines(raw)
        # clean text nodes
        lang=self.options.get_str('lang','en')
        def walk(nodes):
            for n in nodes:
                if n.kind=='text': n.text=clean_text(n.text,self.options,lang)
                elif n.children: walk(n.children)
        walk(inls)
        return inls
    def metadata_plain(self,key):
        return plain_text(self.metadata_inlines(key))
