        # remove last extension
        if '.' in base:
            return base[:base.rfind('.')] or base
        return base
    def _load_single(self,arg,import_stack):
        if arg=='-':
            data=sys.stdin.buffer.read()
            try:
                text=data.decode('utf-8')
            except UnicodeDecodeError:
                raise CrowError(f"-: Error parsing markdown: file - contains invalid UTF-8")
            self.source_file=None; self.parent_display=''; display='-'
            self.options.source_file=None; self.options.source_line=1
            self.filename_for_output=None
        else:
            if not os.path.exists(arg):
                raise CrowError(f"Could not find file '{arg}' for book")
            try:
                with open(arg,'rb') as f: data=f.read()
            except OSError:
                # reference maps read error to invalid UTF-8 message for chapters
                raise CrowError(f"{arg}: Error parsing markdown: file {os.path.basename(str(arg))} contains invalid UTF-8")
            try:
                text=data.decode('utf-8')
            except UnicodeDecodeError:
                raise CrowError(f"{arg}: Error parsing markdown: file {os.path.basename(str(arg))} contains invalid UTF-8")
            self.source_file=None  # options source is None in single mode
            self.parent_display=parent_display(arg)
            display=str(arg)
            self.options.source_file=None; self.options.source_line=1
            self.filename_for_output=self._source_name_for_output(arg)
        # one element numbered
        elem=self._make_file_element(display_path=display, entry_name=display, text=text, entry_type='numbered', explicit=None, shift=0, force_yaml=True, entry_line=None)
        self.elements.append(elem)
    def _load_book_file(self,arg,import_stack):
        import_stack=import_stack or []
        if arg=='-':
            data=sys.stdin.buffer.read()
            text=decode_utf8_config(data)
            self.source_file=None; self.parent_display=''; self.filename_for_output=None
        else:
            if not os.path.exists(arg):
                raise CrowError(f"Could not find file '{arg}' for book")
            data=read_source_bytes(arg)
            text=decode_utf8_config(data)
            self.source_file=str(arg); self.parent_display=parent_display(arg)
            self.filename_for_output=self._source_name_for_output(arg)
        self.options.source_file=self.source_file
        lines=text.splitlines()
        # Segment YAML
        yaml_lines=[]; i=0
        while i < len(lines):
            line=lines[i]
            if line and (line[0] in '+-!@' or line[0].isdigit()):
                break
            yaml_lines.append(line); i+=1
        self.options.source_line=len(yaml_lines) if yaml_lines else 1
        # Parse YAML if present or empty
        if yaml_lines:
            yaml_text='\n'.join(yaml_lines)
            # Edge: a '...' line alone etc: yamlmini skip_empty treats ... as empty and returns Null, need produce YAML error as reference.
            # If first nonblank line is '...', error.
            first_non=None
            for l in yaml_lines:
                if l.strip()!='': first_non=l.strip(); break
            if first_non=='...':
                line_no=len(yaml_lines) if False else (yaml_lines.index(next(l for l in yaml_lines if l.strip()!=''))+1)
                # outer line = that line (1 in tests), inner line 1
                sf=f"{self.source_file}:" if self.source_file else ""
                # format: file:line: Error parsing...
                prefix=f"{self.source_file}:{line_no}: " if self.source_file else ""
                raise CrowError(f"{prefix}Error parsing configuration file: YAML block was not valid YAML: while parsing a node, did not find expected node content at line 1 column 1")
            try:
                ydoc=parse_yaml(yaml_text)
            except YamlError as e:
                prefix=f"{self.source_file}:{len(yaml_lines)}: " if self.source_file else ""
                raise CrowError(f"{prefix}Error parsing configuration file: YAML block was not valid YAML: {e.display()}")
            if ydoc.tag!='Hash':
                raise could_not_parse_book(self.source_file, len(yaml_lines))
            self._apply_config_yaml(ydoc, self.source_file, import_stack)
        else:
            # no yaml lines (empty file or chapter at first line)
            raise could_not_parse_book(self.source_file, None)
        # chapter list from i
        while i < len(lines):
            raw=lines[i]; line_no=i+1; i+=1
            stripped=raw.strip()
            if stripped=='' or stripped.startswith('#'):
                continue
            # parse entry using stripped leading whitespace (in chapter list)
            elem=self._parse_chapter_entry(stripped, line_no, import_stack)
            if elem is not None:
                self.elements.append(elem)
    def _config_err_prefix(self,file,line):
        if file:
            return f"{file}:{line}: "
        return ""
    def _apply_config_yaml(self,ydoc,file_display,import_stack):
        for keyY,valY in ydoc.value:
            if keyY.tag!='String':
                line=keyY.line if hasattr(keyY,'line') else 1
                LOG.error(f"{self._config_err_prefix(file_display,line)}{self.options.error_prefix_converting()}Expected a String as a key, found {yaml_debug(keyY)}",target="crowbook::book")
                continue
            key=keyY.value
            # determine error line
            line=getattr(valY,'line',None) or getattr(keyY,'line',1)
            if valY.tag not in ('Hash','Array','Null'):
                line=getattr(keyY,'line',line)
            if key=='import':
                err=self.options.set_value(key,valY)
                if err:
                    LOG.error(f"{self._config_err_prefix(file_display,line)}{self.options.error_prefix_converting()}{err}",target="crowbook::book"); continue
                # process import
                self._process_import(valY.value, import_stack)
                continue
            err=self.options.set_value(key,valY)
            if err:
                LOG.error(f"{self._config_err_prefix(file_display,line)}{self.options.error_prefix_converting()}{err}",target="crowbook::book")
    def _process_import(self,import_str,import_stack):
        candidate=join_display(self.parent_display, import_str)
        # cycle/simple stack based on absolute path if exists
        canon=None
        try: canon=os.path.abspath(candidate)
        except Exception: canon=candidate
        current_canon=None
        if self.source_arg and self.source_arg!='-':
            try: current_canon=os.path.abspath(str(self.source_arg))
            except: pass
        if canon in (import_stack or []) or (current_canon and canon==current_canon):
            LOG.error(f"Could not find file '{import_str}' for book",target="crowbook::book")
            return
        # If file missing, Book.load would raise Could not find with candidate argument as import_str? Reference uses import_str in message when in same dir, candidate if sub - test ambiguous.
        # For missing, preserve message using import_str if parent empty else candidate? Earlier missing in same dir used import_str (same).
        # We'll let load raise and then adjust: if error is Could not find file '{candidate}' and candidate!=import_str, reference likely candidate. Keep candidate.
        try:
            imported=Book.load(candidate, single=False, cli_pairs=[], autograph_text=None, runtime_lang=self.runtime_lang, import_stack=(import_stack or [])+([current_canon] if current_canon else []))
        except CrowError as e:
            LOG.error(e.msg,target="crowbook::book")
            return
        except PanicError:
            raise
        # merge options present in imported (normal layer only), if not already present in current normal or cli
        imported_parent=parent_display(candidate)
        for key in list(imported.options.present):
            if key=='import': continue
            if key in self.options.present or key in self.options.cli_present:
                continue
            value=imported.options.values.get(key)
            # adjust paths
            typ=SPECS.get(key,(None,None))[0]
            if typ in ('path','template path') and isinstance(value,str) and value not in ('','auto') and not os.path.isabs(value):
                cand=join_display(imported_parent,value)
                # make relative to self.parent_display
                if self.parent_display:
                    try: value=os.path.relpath(cand, self.parent_display)
                    except Exception: value=cand
                else:
                    value=cand
            elif key=='resources.files' and isinstance(value,list):
                newvals=[]
                for v in value:
                    if isinstance(v,str) and not os.path.isabs(v):
                        cand=join_display(imported_parent,v)
                        if self.parent_display:
                            try: v=os.path.relpath(cand,self.parent_display)
                            except: v=cand
                        else: v=cand
                    newvals.append(v)
                value=newvals
            self.options.values[key]=value
            self.options.present.add(key)
    def _parse_chapter_entry(self,line,line_no,import_stack):
        # line is stripped
        sf=self.source_file
        prefix=f"{sf}:{line_no}: " if sf else ""
        if line.startswith('@'):
            # must be '@' + whitespace + non-empty title
            if len(line)<2 or not line[1].isspace() or line[1:].strip()=='':
                raise CrowError(f"{prefix}Error parsing configuration file: found invalid part definition in the chapter list")
            title_text=line[1:].strip()
            # Parse title as markdown blocks (for weird cases)
            parser=MdParser(superscript=self.options.get_bool('crowbook.markdown.superscript',False), html_as_text=self.options.get_bool('crowbook.html_as_text',True))
            # title markdown: parse as blocks; if single para, inlines
            blocks=parser.parse(title_text)
            self._clean_blocks(blocks)
            if len(blocks)==1 and blocks[0].kind=='para':
                title_inlines=blocks[0].children; title_blocks=None
            elif len(blocks)==0:
                title_inlines=[]; title_blocks=None
            else:
                title_inlines=None; title_blocks=blocks
            return Element('part',title_inlines=title_inlines,title_blocks=title_blocks,title_raw=title_text,line=line_no)
        first=line[0]
        if first=='+':
            cand=line[1:].strip(); typ='numbered'; explicit=None; shift=0
            if cand=='': raise CrowError(f"{prefix}Error parsing configuration file: no chapter name specified")
            if any(c.isspace() for c in cand): raise CrowError(f"{prefix}Error parsing configuration file: error.chapter_whitespace")
            return self._load_chapter_file(cand,typ,explicit,shift,line_no)
        if first=='-':
            count=0
            while count < len(line) and line[count]=='-': count+=1
            cand=line[count:].strip()
            if cand=='': raise CrowError(f"{prefix}Error parsing configuration file: no chapter name specified")
            if any(c.isspace() for c in cand): raise CrowError(f"{prefix}Error parsing configuration file: error.chapter_whitespace")
            if count==1: typ='unnumbered'; shift=0
            else: typ='subchapter'; shift=count-1
            return self._load_chapter_file(cand,typ,None,shift,line_no)
        if first=='!':
            cand=line[1:].strip(); typ='hidden'; shift=0
            if cand=='': raise CrowError(f"{prefix}Error parsing configuration file: no chapter name specified")
            if any(c.isspace() for c in cand): raise CrowError(f"{prefix}Error parsing configuration file: error.chapter_whitespace")
            return self._load_chapter_file(cand,typ,None,shift,line_no)
        if first.isdigit():
            if '.' not in line:
                raise CrowError(f"{prefix}Error parsing configuration file: ill-formatted line specifying chapter number")
            num_str,remainder=line.split('.',1)
            # Rust i32 parse
            try:
                if not re.fullmatch(r'[0-9]+',num_str):
                    raise ValueError('invalid digit found in string')
                num=int(num_str)
                if num>2147483647:
                    raise OverflowError('number too large to fit in target type')
            except OverflowError as e:
                raise CrowError(f"{prefix}Error parsing configuration file: error parsing chapter number: {e}")
            except Exception:
                raise CrowError(f"{prefix}Error parsing configuration file: error parsing chapter number: invalid digit found in string")
            # filename candidate: skip first char of remainder
            if remainder=='' :
                raise PanicError("src/lib/book.rs:446:38","byte index 1 is out of bounds of ``")
            cand=remainder[1:].strip() if len(remainder)>=1 else ''
            if cand=='':
                raise PanicError("src/lib/book.rs:446:38","byte index 1 is out of bounds of ``")
            if any(c.isspace() for c in cand): raise CrowError(f"{prefix}Error parsing configuration file: error.chapter_whitespace")
            return self._load_chapter_file(cand,'numbered',num,0,line_no)
        raise CrowError(f"{prefix}Error parsing configuration file: found invalid chapter definition in the chapter list")
    def _load_chapter_file(self,entry_name,typ,explicit,shift,line_no):
        sf=self.source_file; prefix=f"{sf}:{line_no}: " if sf else ""
        candidate=join_display(self.parent_display, entry_name)
        if not os.path.exists(candidate):
            # Reference message uses candidate if book has directory, else entry_name (same as candidate in that case)
            raise CrowError(f"{prefix}Could not find file '{candidate}' for book chapter")
        try:
            with open(candidate,'rb') as f: data=f.read()
        except OSError:
            raise CrowError(f"{prefix}Error parsing markdown: file {candidate} contains invalid UTF-8")
        try:
            text=data.decode('utf-8')
        except UnicodeDecodeError:
            raise CrowError(f"{prefix}Error parsing markdown: file {candidate} contains invalid UTF-8")
        return self._make_file_element(display_path=candidate, entry_name=entry_name, text=text, entry_type=typ, explicit=explicit, shift=shift, force_yaml=False, entry_line=line_no)
    def _extract_yaml_frontmatter(self,text):
        # returns (remaining_text, yaml_doc_or_None, candidate_or_None, yaml_error_or_None)
        lines=text.splitlines()
        if not lines or lines[0]!='---':
            return text,None,None,None
        # find closing line index >1? Need at least one content line (closing cannot be immediate next line)
        close_idx=None
        for idx in range(1,len(lines)):
            if lines[idx]=='---':
                close_idx=idx; break
        if close_idx is None or close_idx==1:
            return text,None,None,None
        candidate='\n'.join(lines[:close_idx+1])+'\n'
        remaining='\n'.join(lines[close_idx+1:])
        # Preserve leading? remaining may not end newline; parser handles.
        try:
            ydoc=parse_yaml(candidate)
        except YamlError as e:
            return remaining,None,candidate,e
        return remaining,ydoc,candidate,None
    def _apply_inline_yaml(self,ydoc):
        if ydoc is None or ydoc.tag!='Hash':
            return
        for keyY,valY in ydoc.value:
            # snapshot old for verbose
            old_present=False; old_val=None; old_key_str=None
            if isinstance(keyY,Y) and keyY.tag=='String':
                old_key_str=keyY.value
                if old_key_str in self.options.values and old_key_str in self.options.present:
                    old_present=True; old_val=self.options.values.get(old_key_str)
            err=None
            if keyY.tag!='String':
                err=f"Expected a String as a key, found {yaml_debug(keyY)}"
            else:
                if keyY.value=='import':
                    # inline import? Probably set normally then process? In single mode YAML import maybe loads book options if absent like config - obscure. Treat like config import: set then process.
                    err=self.options.set_value(keyY.value,valY)
                    if not err:
                        self._process_import(valY.value, [])
                else:
                    err=self.options.set_value(keyY.value,valY)
            if err:
                src=""
                if self.options.source_file:
                    src=f"{self.options.source_file}:{self.options.source_line}: "
                LOG.error(f"Inline YAML block could not set {yaml_debug(keyY)} to {yaml_debug(valY)}: {src}{self.options.error_prefix_converting()}{err}",target="crowbook::book")
            else:
                # verbose replaced debug
                if old_present and old_key_str:
                    # construct old yaml
                    oldY=self._python_to_yaml(old_val,old_key_str)
                    LOG.debug(f"Inline YAML block replaced {yaml_debug(keyY)} previously set to {yaml_debug(oldY)} to {yaml_debug(valY)}",target="crowbook::book")
    def _python_to_yaml(self,val,key=None):
        if isinstance(val,bool): return Y('Boolean',val)
        if isinstance(val,int): return Y('Integer',val)
        if isinstance(val,list): return Y('Array',[self._python_to_yaml(x) for x in val])
        if val is None: return Y('Null',None)
        return Y('String',str(val))
    def _make_file_element(self,display_path,entry_name,text,entry_type,explicit,shift,force_yaml,entry_line):
        original_text=text
        # YAML frontmatter handling
        use_yaml=force_yaml or self.options.get_bool('input.yaml_blocks',False)
        if use_yaml:
            remaining,ydoc,candidate,yerr=self._extract_yaml_frontmatter(text)
            if candidate is not None:
                if yerr is not None:
                    LOG.error(f"Found something that looked like a YAML block:\n{candidate}",target="crowbook::book")
                    LOG.error(f"... but it didn't parse correctly as YAML('{yerr.display()}'), so treating it like Markdown.",target="crowbook::book")
                    text=remaining
                else:
                    text=remaining
                    self._apply_inline_yaml(ydoc)
            else:
                # No block: verbose debug (?) In yaml_blocks true mode, reference may not log ignoring.
                pass
        else:
            # Reference logs Ignoring YAML block per chapter in verbose even if none (empty suffix)
            LOG.debug("Ignoring YAML block:\n",target="crowbook::book")
        parser=MdParser(superscript=self.options.get_bool('crowbook.markdown.superscript',False), html_as_text=self.options.get_bool('crowbook.html_as_text',True))
        try:
            blocks=parser.parse(text)
        except Exception as e:
            # generic parse errors not expected
            raise CrowError(f"{display_path}: Error parsing markdown: {e}")
        # Convert unresolved footnote refs to literal text, clean, shift headings
        self._resolve_footnote_refs(blocks, parser.footnotes)
        # Also footnote def blocks need resolve internal footnote refs? Clean later.
        for label,fb in parser.footnotes.items():
            self._resolve_footnote_refs(fb, parser.footnotes)
        self._clean_blocks(blocks)
        for fb in parser.footnotes.values():
            self._clean_blocks(fb)
        if shift:
            # check headings in doc order
            headings=[]
            self._collect_headings(blocks,headings)
            for fb in parser.footnotes.values(): self._collect_headings(fb,headings)
            for h in headings:
                newlevel=h.level+shift
                if newlevel>6:
                    raise CrowError(f"{display_path}: Error parsing markdown: this subchapter contains a heading that, when adjusted, is not in the right range ({newlevel} instead of [0-6])")
                h.level=newlevel
        elem=Element('file',filename=entry_name,display_path=display_path,blocks=blocks,footnotes=parser.footnotes,footnote_order=parser.footnote_order,entry_type=entry_type,explicit=explicit,shift=shift,entry_line=entry_line,source_text=text,original_text=original_text)
        return elem
    def _collect_headings(self,blocks,out):
        for b in blocks:
            if b.kind=='heading': out.append(b)
            # children are inlines for heading; for containers children may be blocks or items
            if b.kind in ('blockquote',):
                self._collect_headings(b.children,out)
            elif b.kind=='list':
                for item in b.children: self._collect_headings(item.children,out)
            elif b.kind=='deflist':
                for term,defs in b.items:
                    for d in defs: self._collect_headings(d,out)
    def _resolve_footnote_refs(self,blocks,footnotes):
        # walk blocks/inlines converting unresolved footnoteref to text
        def walk_inlines(inls):
            new=[]
            for n in inls:
                if n.kind=='footnoteref' and n.label not in footnotes:
                    new.append(N('text',text=f"[^{n.label}]"))
                else:
                    if n.children: n.children=walk_inlines(n.children)
                    new.append(n)
            return new
        def walk_blocks(blks):
            for b in blks:
                if b.kind in ('para','heading'):
                    b.children=walk_inlines(b.children)
                elif b.kind=='blockquote': walk_blocks(b.children)
                elif b.kind=='list':
                    for item in b.children: walk_blocks(item.children)
                elif b.kind=='table':
                    b.headers=[walk_inlines(h) for h in b.headers]; b.rows=[[walk_inlines(c) for c in row] for row in b.rows]
                elif b.kind=='deflist':
                    b.items=[(walk_inlines(term), [ (walk_blocks(d) or d) for d in defs]) for term,defs in b.items]
            return blks
        walk_blocks(blocks)
    def _clean_blocks(self,blocks):
        lang=self.options.get_str('lang','en') if self.options else 'en'
        def walk_inlines(inls):
            for n in inls:
                if n.kind=='text':
                    n.text=clean_text(n.text,self.options,lang)
                elif n.children:
                    walk_inlines(n.children)
            return inls
        def walk_blocks(blks):
            for b in blks:
                if b.kind in ('para','heading'): walk_inlines(b.children)
                elif b.kind=='blockquote': walk_blocks(b.children)
                elif b.kind=='list':
                    for item in b.children: walk_blocks(item.children)
                elif b.kind=='table':
                    for h in b.headers: walk_inlines(h)
                    for row in b.rows:
                        for c in row: walk_inlines(c)
                elif b.kind=='deflist':
                    for term,defs in b.items:
                        walk_inlines(term)
                        for d in defs: walk_blocks(d)
        walk_blocks(blocks)
    def _postprocess(self):
        # Synthetic headings, link ids, numbering
        # First synthetic
        for elem in self.elements:
            if elem.kind!='file': continue
            has_l1=any(b.kind=='heading' and b.level==1 for b in elem.blocks)
            if elem.entry_type=='numbered' and not has_l1:
                elem.blocks.insert(0,N('heading',[],level=1,synthetic=True))
            elif self.options.get_bool('crowbook.files_mean_chapters',False) and not has_l1 and elem.entry_type!='subchapter':
                # Guess: files mean chapters will insert a heading (numbered behavior?) - to be refined.
                # For unnumbered type, an empty H1 would be visible as empty heading; maybe not. Check behaviour later by tests comparing.
                pass
        # Assign link ids in document order (top-level and nested headings)
        link_counter=1
        def assign_links_blocks(blks):
            nonlocal link_counter
            for b in blks:
                if b.kind=='heading':
                    b.link_id=link_counter; link_counter+=1
                if b.kind=='blockquote': assign_links_blocks(b.children)
                elif b.kind=='list':
                    for item in b.children: assign_links_blocks(item.children)
                elif b.kind=='deflist':
                    for term,defs in b.items:
                        for d in defs: assign_links_blocks(d)
        for elem in self.elements:
            if elem.kind=='part':
                elem.link_id=link_counter; link_counter+=1
                if getattr(elem,'title_blocks',None):
                    assign_links_blocks(elem.title_blocks)
            elif elem.kind=='file':
                assign_links_blocks(elem.blocks)
                # footnote def heading links after main blocks? (rare)
                for label in elem.footnote_order:
                    if label in elem.footnotes: assign_links_blocks(elem.footnotes[label])
        # Numbering
        num_depth=self.options.get_int('rendering.num_depth',1)
        self.num_depth=num_depth
        part_counter=0; chapter_counter=0
        counters=[0]*7
        part_roman=self.options.get_bool('rendering.part.roman_numerals',True)
        chap_roman=self.options.get_bool('rendering.chapter.roman_numerals',False)
        reset_counter=self.options.get_bool('rendering.part.reset_counter',True)
        def fmt_chapter(n):
            return roman(n) if chap_roman else str(n)
        for elem in self.elements:
            if elem.kind=='part':
                part_counter+=1; elem.number=part_counter; elem.number_str=roman(part_counter) if part_roman else str(part_counter)
                elem.header=self.options.get_str('rendering.part') if self.options.is_present('rendering.part') and self.options.get('rendering.part') is not None else locmod.loc_book(self.options.get_str('lang','en'),'part')
                counters[0]=part_counter
                if reset_counter:
                    chapter_counter=0; counters[1:]=[0]*6
                else:
                    counters[2:]=[0]*5
                continue
            if elem.kind!='file': continue
            explicit_pending=elem.explicit
            for b in elem.blocks:
                if b.kind!='heading': continue
                b.numbered=False; b.number=None; b.number_str=None; b.hidden=False
                if b.level==1:
                    if elem.entry_type=='hidden':
                        b.hidden=True; b.numbered=False
                        # counters[1] not incremented; deeper reset?
                        counters[2:]=[0]*5
                    elif elem.entry_type=='numbered':
                        if explicit_pending is not None:
                            chapter_counter=explicit_pending; explicit_pending=None
                        else:
                            chapter_counter+=1
                        counters[1]=chapter_counter; counters[2:]=[0]*5
                        if num_depth>=1:
                            b.numbered=True; b.number=chapter_counter; b.number_str=fmt_chapter(chapter_counter)
                    elif elem.entry_type=='unnumbered':
                        b.numbered=False; counters[2:]=[0]*5
                        # counters[1] stays as last numbered? For subsequent H2 numbers, likely based on current chapter_counter (0 if none) - keep counters[1]=chapter_counter
                        counters[1]=chapter_counter
                    else:
                        b.numbered=False
                elif b.level>=2:
