def normalize_lang(lang):
    if not lang: return ''
    first=str(lang).strip().split()[0].lower()
    aliases={'py':'python','python3':'python','rs':'rust','js':'javascript','ts':'javascript','c++':'cpp','cxx':'cpp','h':'c','hpp':'cpp','sh':'bash','shell':'bash','zsh':'bash','yml':'yaml','htm':'html','xhtml':'html','xml':'html'}
