KNOWN_LANGS=set(list(KEYWORDS.keys())+['html','css','json','yaml','toml','markdown','md','text','plain','xml','sql','php','perl','lua','r','scala','kotlin','swift','objective-c','haskell','ocaml','erlang','elixir','clojure','lisp','scheme','makefile','cmake','dockerfile','diff','ini'])

def tokenize_line(line,lang,theme):
    """Return list of (styletuple, text) granular segments for a single line (no newline)."""
    lang=normalize_lang(lang)
    if not lang or lang in ('text','plain') or lang not in KNOWN_LANGS:
        return [(_style(theme,'default'),line)] if line else []
    if lang=='html':
        return _tokenize_html(line,theme)
    segs=[]; i=0
    keywords=KEYWORDS.get(lang,set())
    builtins=BUILTINS.get(lang,set())
    # state for block comments not carried across lines (handled by caller special? We'll keep simple line-local; multi-line block comments parsed incorrectly beyond first line)
    while i < len(line):
        rest=line[i:]
        # comments
        if lang in ('python','ruby','bash','sh','yaml','toml','perl','r','makefile','cmake','dockerfile'):
            if rest.startswith('#'):
                segs.append((_style(theme,'comment'),rest)); break
        if lang not in ('python',):
            if rest.startswith('//'):
                segs.append((_style(theme,'comment'),rest)); break
            if rest.startswith('/*'):
                end=rest.find('*/',2)
                if end==-1:
                    segs.append((_style(theme,'comment'),rest)); break
                else:
                    segs.append((_style(theme,'comment'),rest[:end+2])); i+=end+2; continue
            if lang in ('html','xml') and rest.startswith('<!--'):
                end=rest.find('-->',4); 
                if end==-1: segs.append((_style(theme,'comment'),rest)); break
                segs.append((_style(theme,'comment'),rest[:end+3])); i+=end+3; continue
        if lang=='sql' and rest.startswith('--'):
            segs.append((_style(theme,'comment'),rest)); break
        ch=line[i]
        # strings
        if ch in ('"',"'",'`'):
            quote=ch
            # triple quotes python
            if lang=='python' and rest.startswith(quote*3):
                end=rest.find(quote*3,3)
                if end==-1:
                    segs.append((_style(theme,'string'),rest)); break
                segs.append((_style(theme,'string'),rest[:end+3])); i+=end+3; continue
            j=i+1
            while j < len(line):
                if line[j]=='\\' and j+1 < len(line): j+=2; continue
                if line[j]==quote: j+=1; break
                j+=1
            segs.append((_style(theme,'string'),line[i:j])); i=j; continue
        # numbers
        if ch.isdigit() or (ch=='.' and i+1 < len(line) and line[i+1].isdigit()):
            m=re.match(r'(0x[0-9a-fA-F]+|0b[01]+|[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+)',rest)
            if m:
                segs.append((_style(theme,'number'),m.group(0))); i+=len(m.group(0)); continue
        # identifiers / keywords
        if ch.isalpha() or ch=='_' or (lang=='rust' and ch=='#'):
            m=re.match(r'[A-Za-z_][A-Za-z0-9_]*',rest)
            if m:
                word=m.group(0); j=i+len(word)
                # function def name in python: previous seg text endswith 'def '
                prev_text=''.join(t for _,t in segs)
                is_def_name = bool(re.search(r'\bdef\s+$',prev_text)) if lang=='python' else False
                is_class_name = bool(re.search(r'\b(class|struct|enum|trait|impl)\s+$',prev_text))
                # look ahead for '('
                k=j
                while k < len(line) and line[k]==' ': k+=1
                if word in keywords:
                    # Keyword may include following space in syntect range for python def/return (HTML merges in a way) - Keep word only; adjacent default space separate.
                    segs.append((_style(theme,'keyword'),word))
                elif is_def_name:
                    segs.append((_style(theme,'entity_func'),word))
                elif is_class_name:
                    segs.append((_style(theme,'type'),word))
                elif word in builtins and k < len(line) and line[k]=='(':
                    segs.append((_style(theme,'builtin'),word))
                elif k < len(line) and line[k]=='(':
                    # General function call: InspiredGitHub often default / entity? Keep default for most, python print builtins above.
                    # In many grammars function name has function color but unknown. Use default to match syntect for user functions in python (f( was default)
                    segs.append((_style(theme,'default'),word))
                elif word and word[0].isupper() and lang in ('rust','java','cpp','c','go','javascript'):
                    segs.append((_style(theme,'type'),word))
                else:
                    segs.append((_style(theme,'default'),word))
                i=j; continue
        # operators / punctuation granular
        if ch in '=+-%*/<>&|!^~':
            # group operator chars? syntect token often single, but == etc group. Group sequential op chars
            j=i
            while j < len(line) and line[j] in '=+-%*/<>&|!^~': j+=1
            # avoid grouping // already handled; avoid grouping a closing html >> weird
            style=_style(theme,'operator') if lang=='python' else _style(theme,'default')
            # For InspiredGitHub python '=' keyword bold; '+ ' in sample was keyword and included a space in merged span due spaces default? Our merge will keep.
            segs.append((style,line[i:j])); i=j; continue
        # single char default (punct/spaces)
        segs.append((_style(theme,'default'),ch)); i+=1
    return segs

def _tokenize_html(line,theme):
    segs=[]; i=0
    while i < len(line):
        if line.startswith('<!--',i):
            end=line.find('-->',i+4)
            if end==-1: segs.append((_style(theme,'comment'),line[i:])); break
            segs.append((_style(theme,'comment'),line[i:end+3])); i=end+3; continue
        if line[i]=='<':
            # tag start
            segs.append((_style(theme,'default'),'<')); i+=1
            if i < len(line) and line[i]=='/':
                segs.append((_style(theme,'default'),'/')); i+=1
            m=re.match(r'[A-Za-z][A-Za-z0-9-]*',line[i:])
            if m:
                segs.append((_style(theme,'tag'),m.group(0))); i+=len(m.group(0))
            # attributes until >
            while i < len(line) and line[i]!='>':
                if line[i].isspace():
                    j=i
                    while j < len(line) and line[j].isspace(): j+=1
                    segs.append((_style(theme,'default'),line[i:j])); i=j; continue
                if line[i] in ('"',"'"):
                    q=line[i]; j=i+1
                    while j < len(line) and line[j]!=q: j+=1
                    if j < len(line): j+=1
                    segs.append((_style(theme,'string'),line[i:j])); i=j; continue
                m=re.match(r'[A-Za-z_:][-A-Za-z0-9_:.]*',line[i:])
                if m:
                    segs.append((_style(theme,'attr'),m.group(0))); i+=len(m.group(0)); continue
                segs.append((_style(theme,'default'),line[i])); i+=1
            if i < len(line) and line[i]=='>':
                segs.append((_style(theme,'default'),'>')); i+=1
            continue
        # text up to <
        j=line.find('<',i)
        if j==-1: j=len(line)
        segs.append((_style(theme,'default'),line[i:j])); i=j
    return segs

def merge_segments(segs):
    merged=[]
    for style,text in segs:
        if not text: continue
        if merged and merged[-1][0]==style:
            merged[-1]=(style,merged[-1][1]+text)
        else:
            merged.append((style,text))
    return merged

def style_attr(style):
    color,flags=style
    parts=[]
    if 'b' in flags: parts.append('font-weight:bold;')
    if 'i' in flags: parts.append('font-style:italic;')
    if 'u' in flags: parts.append('text-decoration:underline;')
    parts.append(f'color:{color};')
    return ''.join(parts)

def escape_code_html(s):
    return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'",'&#39;')

def highlight_html_code(text,lang,theme_name):
    theme=get_theme(theme_name) or THEMES['InspiredGitHub']
    # text is code content ending with newline if non-empty
    if text=='':
        return '\n'
    lines=text.split('\n')
    # split gives final '' if ends with \n; syntect iterates lines including that? Output has a blank line before </pre> -> one extra \n after last content: renderer writes each highlighted line plus \n, and final split '' produces just \n in our joining logic below.
    out=[]
    for idx,line in enumerate(lines):
        if idx==len(lines)-1 and line=='' and text.endswith('\n'):
            out.append('\n'); continue
        segs=merge_segments(tokenize_line(line,lang,theme))
        if line=='':
            out.append('\n'); continue
        for style,seg in segs:
            out.append(f'<span style="{style_attr(style)}">{escape_code_html(seg)}</span>')
        out.append('\n')
    return ''.join(out)

def rgb_str(hexcolor):
    h=hexcolor.lstrip('#')
    r=int(h[0:2],16)/255; g=int(h[2:4],16)/255; b=int(h[4:6],16)/255
    def fmt(x):
        # Rust f32 Display (?) reference prints like 0.19607843, 0, 0.5254902
        # That's representation of (x as f32). Python formatting reproducing Rust: use repr of float32 converted
        import struct
        f=struct.unpack('f',struct.pack('f',x))[0]
        if f==0: return '0'
        if f==1: return '1'
        s=('%.15f'%f).rstrip('0').rstrip('.')
        return s
    return f"{fmt(r)}, {fmt(g)}, {fmt(b)}"
