def esc_text(s):
    return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
def esc_attr_href(s):
    return str(s).replace('&','&amp;')

def b64_nopad(data):
    return base64.b64encode(data).decode('ascii').rstrip('=')

def mime_for_ext(ext):
    ext=ext.lower().lstrip('.')
    return {'png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','gif':'image/gif','svg':'image/svg+xml','webp':'image/webp','ico':'image/x-icon','bmp':'image/bmp','tif':'image/tiff','tiff':'image/tiff'}.get(ext, f'image/{ext}' if ext else 'image/png')

def with_extension_md(path):
    # Rust Path::with_extension("md")
    if path=='':
        return ''
    # split dir/file
    if '/' in path:
        dirp,fn=path.rsplit('/',1); prefix=dirp+'/'
    else:
        prefix=''; fn=path
    if fn in ('.','..'):
        return path+'.md'  # approx
    # Rust: file stem is up to first dot if file name begins with dot? For our use, Rust with_extension considers extension after last dot, except if filename begins with dot and has no other dots.
    if '.' in fn:
        # find last dot that is not first char
        idx=fn.rfind('.')
        if idx>0:
            return prefix+fn[:idx]+'.md'
    return path+'.md'

class ResourceHandler:
    def __init__(self,book,mode):
        self.book=book; self.mode=mode
        self.image_map={}; self.images=[]  # list of (arcname, source_candidate_display, data_bytes)
        self.image_counter=0
        # map chapter source keys to element idx
        self.link_map={}
        for idx,elem in enumerate(book.elements):
            if elem.kind=='file':
                # keys: entry_name (book-relative) and display_path maybe
                for key in {elem.filename, elem.display_path}:
                    if key: self.link_map[key]=idx
        # resources files
        self.resource_files=[]
        vals=book.options.get('resources.files')
        if isinstance(vals,list): self.resource_files=list(vals)
    def _image_candidate(self,dest,source_elem):
        opts=self.book.options
        # source dir relative to book (entry filename dir)
        source_entry=source_elem.filename if source_elem and source_elem.kind=='file' else ''
        source_dir=os.path.dirname(source_entry) if source_entry else ''
        # display candidate as reference: base path handling simplified
        base=None
        if opts.is_present('resources.base_path') and opts.get('resources.base_path') is not None:
            base=opts.get_str('resources.base_path')
            candidate_disp=os.path.join(self.book.parent_display, base, dest) if self.book.parent_display else os.path.join(base,dest)
            # For root book with base '.', this gives ./dest
            return candidate_disp
        base_img=opts.get_str('resources.base_path.images','.')
        # If base_img is default '.' - images relative to markdown file: candidate = source display dir + dest, but display uses ./ when no source dir
        if base_img in ('.',''):
            if source_elem:
                disp_dir=os.path.dirname(source_elem.display_path)
                if disp_dir:
                    return os.path.join(disp_dir,dest)
                else:
                    return './'+dest if not dest.startswith('./') else dest
            return './'+dest
        else:
            # relative to book parent + base_img
            return os.path.join(self.book.parent_display, base_img, dest) if self.book.parent_display else os.path.join(base_img,dest)
    def resolve_image(self,dest,source_elem):
        if '://' in str(dest):
            LOG.warn(f"Resources: book includes non-local image {dest}, which might cause problem for proper inclusion.",target="crowbook::resource_handler")
            return str(dest)
        candidate=self._image_candidate(str(dest),source_elem)
        # Actual file path: candidate as is relative cwd (book parent display already included where applicable)
        if not os.path.exists(candidate):
            srcname=source_elem.display_path if source_elem else self.book.source_file or ''
            raise CrowError(f"{srcname}: Could not find file '{candidate}' for image")
        try:
            with open(candidate,'rb') as f: data=f.read()
        except OSError:
            srcname=source_elem.display_path if source_elem else ''
            raise CrowError(f"{srcname}: Could not find file '{candidate}' for image")
        if self.mode=='standalone':
            ext=os.path.splitext(str(dest))[1]
            return f"data:{mime_for_ext(ext)};base64,{b64_nopad(data)}"
        else:
            # assign name dedup by candidate absolute/normalized
            key=os.path.abspath(candidate)
            if key in self.image_map:
                return self.image_map[key]
            ext=os.path.splitext(str(dest))[1]  # includes dot
            arc=f"images/image_{self.image_counter}{ext}"
            self.image_counter+=1
            self.image_map[key]=arc
            self.images.append((arc,candidate,data))
            return arc
    def add_image_file(self,path_option_value):
        # Used for cover/icon: path_option_value is relative to book parent (effective option value already import-adjusted)
        dest=str(path_option_value)
        if '://' in dest:
            return dest
        candidate=os.path.join(self.book.parent_display,dest) if self.book.parent_display else dest
        # For standalone icon handler, resolve_image with a fake source? Use direct: if mode standalone, data URI
        if self.mode=='standalone':
            # Mimic resolve_image but candidate display for errors is ??? We'll let caller handle missing in some contexts.
            if not os.path.exists(candidate):
                # Reference behavior for missing icon/cover differs by renderer; raise generic CrowError to be handled caller
                raise CrowError(f"Could not find file '{candidate}' for image")
            data=open(candidate,'rb').read(); ext=os.path.splitext(dest)[1]
            return f"data:{mime_for_ext(ext)};base64,{b64_nopad(data)}"
        else:
            if not os.path.exists(candidate):
                raise CrowError(f"Could not find file '{candidate}' for image")
            data=open(candidate,'rb').read(); key=os.path.abspath(candidate)
            if key in self.image_map: return self.image_map[key]
            ext=os.path.splitext(dest)[1]; arc=f"images/image_{self.image_counter}{ext}"; self.image_counter+=1; self.image_map[key]=arc; self.images.append((arc,candidate,data)); return arc
    def resolve_link(self,dest,source_elem):
        dest=str(dest)
        if '://' in dest:
            return dest
        # Try internal chapter match
        found_idx=None; matched_key=None
        # key candidates based on source location
        source_entry=source_elem.filename if source_elem and source_elem.kind=='file' else ''
        source_dir=os.path.dirname(source_entry) if source_entry else ''
        opts=self.book.options
        joined_candidates=[]
        if opts.is_present('resources.base_path') and opts.get('resources.base_path') is not None:
            joined_candidates.append(os.path.join(opts.get_str('resources.base_path'),dest))
        elif opts.is_present('resources.base_path.links') and opts.get('resources.base_path.links') is not None:
            joined_candidates.append(os.path.join(opts.get_str('resources.base_path.links'),dest))
        elif source_dir:
            joined_candidates.append(os.path.join(source_dir,dest))
        joined_candidates.append(dest)
        for jc in joined_candidates:
            for cand in (jc, with_extension_md(jc)):
                if cand in self.link_map:
                    found_idx=self.link_map[cand]; matched_key=cand; break
            if found_idx is not None: break
        if found_idx is not None:
            if self.mode=='standalone':
                return f"#chapter-{found_idx}"
            elif self.mode=='dir':
                # Fragment handling: if original contained #link-... keep? Extract after last # if looks like link-N? We'll preserve any fragment portion after first # if it starts link- or chapter-
                frag=self._fragment(dest)
                base=f"chapter_{found_idx:03d}.html"
                return base+(f"#{frag}" if frag else "")
            elif self.mode in ('epub','epub2','epub3'):
                frag=self._fragment(dest)
                base=f"chapter_{found_idx:03d}.xhtml"
                return base+(f"#{frag}" if frag else "")
            else:
                return f"#chapter-{found_idx}"
        # Resources files match by basename/path
        for rf in self.resource_files:
            if dest==rf or os.path.basename(dest)==os.path.basename(str(rf)):
                out_path=self.book.options.get_str('resources.out_path','data')
                return f"{out_path}/{os.path.basename(str(rf))}"
        LOG.warn(f"Resources: could not find an in-book match for link {dest} or {with_extension_md(dest)}",target="crowbook::resource_handler")
        return dest
    def _fragment(self,dest):
        # return fragment if dest has a # after a filename (not at pos0)
        if '#' in dest:
            before, frag=dest.split('#',1)
            if before and frag:
                return frag
        return None

def book_uses_codeblocks(book):
    found=False
    def walk(blks):
        nonlocal found
        for b in blks:
            if b.kind=='codeblock': found=True
            if b.kind=='blockquote': walk(b.children)
            elif b.kind=='list':
                for it in b.children: walk(it.children)
            elif b.kind=='deflist':
                for _,defs in b.items:
                    for d in defs: walk(d)
    for e in book.elements:
        if e.kind=='file':
            walk(e.blocks)
            for fb in e.footnotes.values(): walk(fb)
    return found

class HtmlRenderer:
    def __init__(self,book,mode='standalone',epub_version=2):
        self.book=book; self.mode=mode; self.epub_version=epub_version
        self.resources=ResourceHandler(book,'standalone' if mode=='standalone' else mode)
        self.para_counter=0
        self.current_element=None; self.current_index=0
        self.current_footnotes=[]  # labels refs order
        self.pending_initial=True
        opts=book.options
        self.lang=opts.get_str('lang','en')
        # highlight validation
        raw_hl=opts.get_str('rendering.highlight','syntect')
        if raw_hl not in ('syntect','highlight.js','none'):
            LOG.error(f"rendering.highlight set to '{raw_hl}', not a valid value",target="crowbook::bookoptions")  # target unknown; verbose target may differ
            self.highlight='none'
        else:
            self.highlight=raw_hl
        # theme
        if mode in ('epub','epub2','epub3'):
            theme_opt=opts.get('epub.highlight.theme') if opts.is_present('epub.highlight.theme') else None
        else:
            theme_opt=opts.get('html.highlight.theme') if opts.is_present('html.highlight.theme') else None
        self.theme_name=theme_opt if theme_opt is not None else opts.get_str('rendering.highlight.theme','InspiredGitHub')
        self._theme_validated=False
        if self.highlight=='syntect' and book_uses_codeblocks(book):
            self._validate_theme()
    def _validate_theme(self):
        if self._theme_validated: return
        self._theme_validated=True
        if hlmod.get_theme(self.theme_name) is None:
            LOG.error(f"could not set syntect theme to {self.theme_name}, defaulting to \"InspiredGitHub\"",target="crowbook::syntax")
            LOG.info("syntax valid_themes",target="crowbook::syntax")
            self.theme_name='InspiredGitHub'
    # ---------- inline
    def escape_nb(self,text):
        if self.mode in ('epub','epub2','epub3'):
            enabled=self.book.options.get_bool('epub.escape_nb_spaces',True)
        else:
            enabled=self.book.options.get_bool('html.escape_nb_spaces',True)
        if not enabled:
            return esc_text(text)
        # token by regular spaces/tabs/newlines? We'll split preserving spaces using regex tokens separated by ' '
        # Text may contain spaces - split by ' ' only (NNBSP tokens contain \u202f)
        parts=text.split(' ')
        out_parts=[]
        for part in parts:
            if '\u202f' in part:
                replaced=esc_text(part).replace('\u202f','&#160;')
                out_parts.append(f'<span class = "nnbsp">{replaced}</span>')
            else:
                out_parts.append(esc_text(part))
        return ' '.join(out_parts)
    def render_inlines(self,inls,escape_nb=True):
        return ''.join(self.render_inline(n,escape_nb=escape_nb) for n in inls)
    def render_inline(self,n,escape_nb=True):
        k=n.kind
        if k=='text':
            return self.escape_nb(n.text) if escape_nb else esc_text(n.text)
        if k=='softbreak':
            return ' '
        if k=='hardbreak':
            return '<br />\n'
        if k=='code':
            return f"<code>{esc_text(n.text)}</code>"
        if k=='emph':
            return f"<em>{self.render_inlines(n.children,escape_nb)}</em>"
        if k=='strong':
            return f"<b>{self.render_inlines(n.children,escape_nb)}</b>"
        if k=='strike':
            return f"<del>{self.render_inlines(n.children,escape_nb)}</del>"
        if k=='sup':
            return f"<sup>{self.render_inlines(n.children,escape_nb)}</sup>"
        if k=='sub':
            return f"<sub>{self.render_inlines(n.children,escape_nb)}</sub>"
        if k=='html':
            if self.book.options.get_bool('crowbook.html_as_text',True):
                return self.escape_nb(n.text) if escape_nb else esc_text(n.text)
            else:
                return ''
        if k=='link':
            href=self.resources.resolve_link(n.dest,self.current_element)
            title_attr=f' title = "{n.title}"' if n.title is not None else ''
            return f'<a href = "{esc_attr_href(href)}"{title_attr}>{self.render_inlines(n.children,escape_nb)}</a>'
        if k=='image':
            src=self.resources.resolve_image(n.dest,self.current_element)
            alt=esc_text(plain_text(n.children))
            title=n.title if n.title is not None else ''
            return f'<img src = "{esc_attr_href(src)}" title = "{title}" alt = "{alt}" />'
        if k=='footnoteref':
            label=n.label
            if label not in self.current_footnotes:
                self.current_footnotes.append(label)
            if self.mode in ('epub','epub2'):
                return f'<a  href = "#note-dest-{label}"><sup id = "note-source-{label}">[{label}]</sup></a>'
            elif self.mode=='epub3':
                return f'<a epub:type = "noteref" href = "#note-dest-{label}"><sup id = "note-source-{label}">[{label}]</sup></a>'
            else:
                idx=self.current_index+1
                return f'<a class = "footnote_reference" href = "#note-dest-{idx}-{label}" id = "note-source-{idx}-{label}"><sup>[{label}]</sup></a>'
        return self.render_inlines(n.children,escape_nb) if n.children else ''
    def render_inlines_plain_html(self,inls):
        # For TOC titles: same as render (preserves format) in HTML standalone
        return self.render_inlines(inls)
    # ---------- blocks
    def render_blocks(self,blocks):
        return ''.join(self.render_block(b) for b in blocks)
    def render_block(self,b):
        k=b.kind
        if k=='para':
            # standalone image check
            meaningful=[c for c in b.children if not (c.kind=='text' and c.text.strip()=='') and c.kind!='softbreak']
            if len(meaningful)==1 and meaningful[0].kind=='image':
                # consumes pending initial?
                if self.pending_initial:
                    self.pending_initial=False
                img_html=self.render_inline(meaningful[0])
                return f'<div class = "image">\n  {img_html}\n</div>'
            self.para_counter+=1
            pid=self.para_counter
            is_first=False
            initials=self.book.options.get_bool('rendering.initials',False)
            if initials and self.pending_initial:
                # check first meaningful inline is text
                if b.children and b.children[0].kind=='text' and b.children[0].text!='':
                    is_first=True
                self.pending_initial=False
            elif self.pending_initial:
                self.pending_initial=False
            class_attr=' class = "first-para"' if is_first else ''
            if is_first and self.mode in ('epub','epub2','epub3'):
                # render first text char wrapped
                content=self._render_inlines_with_initial(b.children)
            else:
                content=self.render_inlines(b.children)
            return f'<p id = "para-{pid}"{class_attr}>{content}</p>\n'
        if k=='heading':
            return self._render_heading(b)
        if k=='blockquote':
            return f"<blockquote>{self.render_blocks(b.children)}</blockquote>\n"
        if k=='codeblock':
            return self._render_codeblock(b)
        if k=='list':
            return self._render_list(b)
        if k=='deflist':
            out=['<dl>\n']
            for term,defs in b.items:
                out.append(f"<dt>{self.render_inlines(term)}</dt>\n")
                for d in defs:
                    out.append(f"<dd>{self.render_blocks(d)}</dd>\n")
            out.append('\n</dl>\n')
            return ''.join(out)
        if k=='table':
            out=['<div class = "table">\n    <table>\n']
            out.append('<tr>\n')
            for h in b.headers:
                out.append(f"<th>{self.render_inlines(h)}</th>")
            out.append('</tr>\n')
            for row in b.rows:
                out.append('<tr>\n')
                for c in row:
                    out.append(f"<td>{self.render_inlines(c)}</td>")
                out.append('</tr>\n')
            out.append('\n    </table>\n</div>\n')
            return ''.join(out)
        if k=='rule':
            return '<p class = "rule">***</p>\n'
        if k=='htmlblock':
            if self.book.options.get_bool('crowbook.html_as_text',True):
                return f"{self.escape_nb(b.text)}\n"
            else:
                return ''
        return ''
    def _render_inlines_with_initial(self,inls):
        if not inls: return ''
        # clone first text splitting first unicode char
        first=inls[0]
        if first.kind!='text' or not first.text: return self.render_inlines(inls)
        ch=first.text[0]; rest=first.text[1:]
        out=[f'<span class = "initial">{esc_text(ch)}</span>']
        if rest: out.append(self.escape_nb(rest))
        out.append(self.render_inlines(inls[1:]))
        return ''.join(out)
    def _render_heading(self,b):
        # after an L1 heading, next para is first candidate
        # heading itself not para pending weird: pending should be True after heading regardless previous. Set after rendering heading below.
        level=b.level
        link=getattr(b,'link_id',0)
        result=''
        if level==1:
            if getattr(b,'hidden',False):
                result=f'<h1 id = "link-{link}"></h1>'
            else:
                tmpl=self.book.options.get_str('html.chapter.template')
                # variables
                has_number=bool(getattr(b,'numbered',False))
                has_title=(getattr(b,'plain_title','')!='') if hasattr(b,'plain_title') else len(b.children)>0
                header=self.book.options.get_str('rendering.chapter') if self.book.options.is_present('rendering.chapter') and self.book.options.get('rendering.chapter') is not None else locmod.loc_book(self.lang,'chapter')
                ctx={'link':str(link),'has_number':has_number,'header':header,'number':getattr(b,'number_str','') or '','has_title':has_title,'title':self.render_inlines(b.children)}
                try:
                    result=render_template(tmpl,ctx,mode='html')
                except TemplateError as e:
                    raise CrowError(format_template_error_exact(e).rstrip('\n'))
            self.pending_initial=True
            return result
        else:
            prefix=''
            if getattr(b,'numbered',False) and getattr(b,'number_str',None):
                prefix=f"{b.number_str}. "
            result=f'<h{level} id = "link-{link}">{prefix}{self.render_inlines(b.children)}</h{level}>\n'
            # H2+ does not reset pending? Reference: after H1, quote para first. After H2, para not first. So don't set.
            return result
    def _render_codeblock(self,b):
        text=b.text; lang=b.lang or ''
        if self.highlight=='syntect':
            self._validate_theme()
            return f"<pre>{hlmod.highlight_html_code(text,lang,self.theme_name)}</pre>"
        else:
            if lang:
                return f'<pre><code class = "language-{lang}">{esc_text(text)}</code></pre>\n'
            else:
                return f'<pre><code>{text}</code></pre>\n'
    def _render_list(self,b):
        if b.ordered:
            start_attr=f' start = "{b.start}"' if b.start is not None and b.start!=1 else ''
            out=[f'<ol{start_attr}>\n']
            close='</ol>\n'
        else:
            out=['<ul>\n']; close='</ul>\n'
        for item in b.children:
            inner=self.render_blocks(item.children)
            if item.task is not None:
                checked=' checked = ""' if item.task else ''
                out.append(f'<input type = "checkbox" disabled = ""{checked}/>{inner}')
            else:
                out.append(f'<li>{inner}</li>\n')
        out.append(close)
        return ''.join(out)
    # ---------- chapter / part
    def render_part(self,elem):
        tmpl=self.book.options.get_str('html.part.template')
        if elem.title_inlines is not None:
            title_html=self.render_inlines(elem.title_inlines)
        elif elem.title_blocks:
            # render blocks but strip? reference puts blocks html inside h1 var
            title_html=self.render_blocks(elem.title_blocks)
        else:
            title_html=''
        ctx={'header':getattr(elem,'header',locmod.loc_book(self.lang,'part')),'number':getattr(elem,'number_str','') or '','link':str(getattr(elem,'link_id',0)),'title':title_html}
        try:
            return render_template(tmpl,ctx,mode='html')
        except TemplateError as e:
            raise CrowError(format_template_error_exact(e).rstrip('\n'))
    def render_file_content(self,elem,index):
        self.current_element=elem; self.current_index=index; self.current_footnotes=[]; self.pending_initial=True
        content=self.render_blocks(elem.blocks)
        # notes
        if self.current_footnotes:
            content+=self._render_notes(elem)
        return content
    def _render_notes(self,elem):
        side=self.book.options.get_bool('html.side_notes',False)
        labels=list(self.current_footnotes)
        idx=self.current_index+1
        loc_notes=locmod.loc_book(self.lang,'notes')
        if side:
            out=[]
            for label in labels:
                blocks=elem.footnotes.get(label,[])
                blocks_html=self.render_blocks(blocks)
                if self.mode in ('epub','epub2'):
                    out.append(f'<div class = "sidenote">\n<p class = "note-number">\n  <a href = "#note-source-{label}">[{label}]</a>\n</p>\n <a id = "note-dest-{label}" />{blocks_html}\n</div>\n')
                elif self.mode=='epub3':
                    # guess: aside epub type
                    out.append(f'<div class = "sidenote">\n<p class = "note-number">\n  <a href = "#note-source-{label}">[{label}]</a>\n</p>\n <aside epub:type = "footnote" id = "note-dest-{label}">{blocks_html}</aside>\n</div>\n')
                else:
                    out.append(f'<div class = "sidenote">\n<p class = "note-number">\n  <a rel = "footnote" href = "#note-source-{idx}-{label}">[{label}]</a>\n</p>\n <aside class = "footnote" id = "note-dest-{idx}-{label}">{blocks_html}</aside>\n</div>\n')
            return ''.join(out)
        # normal notes by mode
        out=[]
        if self.mode in ('epub','epub2'):
            out.append(f'<div class = "notes" >\n <h2 class = "notes">{loc_notes}</h2>\n<table class = "notes">\n')
            for label in labels:
                blocks_html=self.render_blocks(elem.footnotes.get(label,[]))
                out.append('<tr class = "notes">\n <td class = "note-number">\n  <p class = "note-number">\n')
                out.append(f'  <a href = "#note-source-{label}">[{label}]</a>\n</p>\n\n </td>\n <td class = "note">\n')
                out.append(f'  <a id = "note-dest-{label}" />{blocks_html}\n  </td>\n</tr>\n')
            out.append('</table>\n</div>\n')
            return ''.join(out)
        elif self.mode=='epub3':
            out.append(f'<section class = "notes" epub:type="footnotes">\n <h2 class = "notes">{loc_notes}</h2>\n<table class = "notes">\n')
            for label in labels:
                blocks_html=self.render_blocks(elem.footnotes.get(label,[]))
                out.append('<tr class = "notes">\n <td class = "note-number">\n  <p class = "note-number">\n')
                out.append(f'  <a href = "#note-source-{label}">[{label}]</a>\n</p>\n\n </td>\n <td class = "note">\n')
