    if node.is_part:
        if node.numbered and node.number_str:
            tmpl=book.options.get_str('rendering.part.template')
            ctx={'number':node.number_str,'part_title':renderer.render_inlines(node.title_inlines)}
            try: return render_template(tmpl,ctx)
            except TemplateError: return renderer.render_inlines(node.title_inlines)
        return renderer.render_inlines(node.title_inlines)
    else:
        if node.numbered and node.number_str:
            tmpl=book.options.get_str('rendering.chapter.template')
            ctx={'number':node.number_str,'chapter_title':renderer.render_inlines(node.title_inlines)}
            try: return render_template(tmpl,ctx)
            except TemplateError: return renderer.render_inlines(node.title_inlines)
        return renderer.render_inlines(node.title_inlines)

def toc_title_plain_escaped(book,node):
    # For EPUB toc strings given to epub builder: plain text but with &,<,> escaped (so xml builder double escapes in ncx)
    plain=node.plain
    if node.is_part:
        if node.numbered and node.number_str:
            tmpl=book.options.get_str('rendering.part.template')
            s=tmpl.replace('{{number}}',node.number_str).replace('{{part_title}}',esc_text(plain))
            return s
        return esc_text(plain)
    else:
        if node.numbered and node.number_str:
            tmpl=book.options.get_str('rendering.chapter.template')
            s=tmpl.replace('{{number}}',node.number_str).replace('{{chapter_title}}',esc_text(plain))
            return s
        return esc_text(plain)

def render_toc_list(renderer,nodes,href_fn,indent=4):
    # returns string starting with spaces indent + "<ul>\n" ... + indent + "</ul>\n" ??? check final formatting: root list in final HTML ends with "    </ul>\n" then template has nav closing on next line from template.
    sp=' '*indent
    out=[f"{sp}<ul>\n"]
    for node in nodes:
        title=toc_title_html(renderer,node)
        href=href_fn(node)
        if node.children:
            out.append(f"{sp}  <li>\n")
            out.append(f"{sp}    <a href=\"{href}\">{title}</a>\n")
            out.append(render_toc_list(renderer,node.children,href_fn,indent+4))
            out.append(f"{sp}  </li>\n")
        else:
            out.append(f"{sp}  <li><a href=\"{href}\">{title}</a></li>\n")
    out.append(f"{sp}</ul>\n")
    return ''.join(out)
