def template_candidate(book,value):
    if os.path.isabs(value):
        return value
    opts=book.options
    if opts.is_present('resources.base_path') and opts.get('resources.base_path') is not None:
        base=opts.get_str('resources.base_path')
    else:
        base=opts.get_str('resources.base_path.templates','.')
    # candidate construction: book parent + base + value; if parent empty and base '.' -> ./value
    parts=[]
    if book.parent_display: parts.append(book.parent_display)
    if base: parts.append(base)
    parts.append(value)
    cand=os.path.join(*parts) if parts else value
    # os.path.join('.', 'x') -> './x'; join('sub','.', 'x') -> 'sub/./x'
    return cand

