def get_template(book, option_key, panic_info=None):
    # option_key is template name itself as in options (same string)
    if book.options.is_present(option_key) and book.options.get(option_key) is not None:
        value=book.options.get_str(option_key)
        candidate=template_candidate(book,value)
        if not os.path.exists(candidate):
            if panic_info:
                loc,fileline=panic_info
                raise PanicError(loc, f"called `Result::unwrap()` on an `Err` value: Error {{ source: Source {{ file: Some(\"{book.options.source_file}\"), line: None }}, inner: FileNotFound(\"template '{option_key}'\", \"{candidate}\") }}")
            src=f"{book.options.source_file}: " if book.options.source_file else ""
            raise CrowError(f"{src}Could not find file '{candidate}' for template '{option_key}'")
        try:
            return open(candidate,encoding='utf-8').read()
        except Exception as e:
            src=f"{book.options.source_file}: " if book.options.source_file else ""
            raise CrowError(f"{src}Could not find file '{candidate}' for template '{option_key}'")
    return load_text(f'templates/{option_key}')

def template_candidate(book,value):
    if os.path.isabs(value):
        return value
    opts=book.options
    if opts.is_present('resources.base_path') and opts.get('resources.base_path') is not None:
        base=opts.get_str('resources.base_path')
    else:
        base=opts.get_str('resources.base_path.templates','.')
    # candidate construction: book parent + base + value; if parent empty and base '.' -> ./value
    parts=[]
    if book.parent_display: parts.append(book.parent_display)
    if base: parts.append(base)
    parts.append(value)
    cand=os.path.join(*parts) if parts else value
    # os.path.join('.', 'x') -> './x'; join('sub','.', 'x') -> 'sub/./x'
    return cand

