    return 'data:image/svg+xml;base64,'+b64_nopad(data)

def metadata_context(book,renderer=None):
    opts=book.options
    # Render metadata inlines using an html renderer if provided else a temporary one? Temporary would reset images/links warnings. Standalone uses its renderer.
    # This helper is mostly for epub/tex overridden.
    return {}

def json_data(book):
    opts=book.options
    def line(key,opt_key):
        if opts.is_present(opt_key) and opts.get(opt_key) is not None:
            return f'    "{key}": "{opts.get_str(opt_key)}",\n'
        return '    \n'
    # Based on sampled structure: fields after name are lines (with 4 spaces) or blank lines? Sample with absent fields had blank lines with maybe no spaces? It showed empty lines.
    # Use a template-like construction exactly:
    out=[]
    out.append("\n<script type = 'application/ld+json'>\n")
    out.append("{\n")
    out.append('    "@context": "http://schema.org/",\n')
    out.append('    "@type": "Book",\n')
    out.append(f'    "author": "{opts.get_str("author","")}",\n')
    out.append(f'    "name": "{opts.get_str("title","")}",\n')
    for key,opt in [('version','version'),('alternateName','subtitle'),('keywords','subject'),('license','license'),('about','description')]:
        if opts.is_present(opt) and opts.get(opt) is not None:
            out.append(f'    "{key}": "{opts.get_str(opt)}",\n')
        else:
            out.append('    \n')
    out.append(f'    "inLanguage": "{opts.get_str("lang","en")}"\n')
    out.append('}\n')
    out.append('</script>\n    ')
    return ''.join(out)

def build_css(book,css_option,additional_opt,colors_option=None,renderer=None):
    # renderer unused
    opts=book.options
    add=opts.get_str(additional_opt,'') if opts.is_present(additional_opt) and opts.get(additional_opt) is not None else ''
    ctx={'lang':opts.get_str('lang','en'),'additional_code':add,'title':opts.get_str('title',''),'author':opts.get_str('author','')}
    if colors_option:
        colors_template=get_template(book,colors_option)
        colors=render_tmpl_or_error(colors_template,ctx)
        ctx['colors']=colors
    template=get_template(book,css_option)
    return render_tmpl_or_error(template,ctx)

def build_script(book,renderer):
    opts=book.options
    # common script
    common_template=get_template(book,'html.js',panic_info=("src/lib/html_single.rs:264:52",None) if renderer.mode=='standalone' else None)
    ctx_common={'lang':opts.get_str('lang','en')}
    common=render_tmpl_or_error(common_template,ctx_common)
    if renderer.mode=='dir':
        return common
    template=get_template(book,'html.standalone.js')
    lang=opts.get_str('lang','en')
    ctx={'common_script':common,'one_chapter':opts.get_bool('html.standalone.one_chapter',False),'lang':lang,
         'loc_display_all':locmod.loc_book(lang,'display_all'),'loc_display_one':locmod.loc_book(lang,'display_one'),
         'loc_toc':locmod.loc_book(lang,'toc'),'book_svg':svg_data_uri('book.svg'),'pages_svg':svg_data_uri('pages.svg'),'menu_svg':svg_data_uri('menu.svg')}
    return render_tmpl_or_error(template,ctx)

def chapter_title_for_element(book,renderer,elem):
    # returns title Html string as used in controls / chapter page plain raw handling elsewhere
    if elem.kind=='part':
        tmpl=book.options.get_str('rendering.part.template')
        title_inlines=elem.title_inlines or []
        ctx={'number':getattr(elem,'number_str','') or '','part_title':renderer.render_inlines(title_inlines)}
        try: return render_template(tmpl,ctx)
        except Exception: return renderer.render_inlines(title_inlines)
    # find first top heading
    for b in elem.blocks:
        if b.kind=='heading':
            if getattr(b,'hidden',False):
                return renderer.render_inlines(b.children)
            if getattr(b,'numbered',False) and getattr(b,'number_str',None):
                tmpl=book.options.get_str('rendering.chapter.template')
                ctx={'number':b.number_str,'chapter_title':renderer.render_inlines(b.children)}
                try: return render_template(tmpl,ctx)
                except Exception: pass
            return renderer.render_inlines(b.children)
    return ''

def chapter_plain_title(book,elem):
    if elem.kind=='part':
        plain=getattr(elem,'plain_title','')
        if getattr(elem,'number_str',None):
            tmpl=book.options.get_str('rendering.part.template')
            return tmpl.replace('{{number}}',elem.number_str).replace('{{part_title}}',plain)
        return plain
    for b in elem.blocks:
        if b.kind=='heading':
            plain=getattr(b,'plain_title',plain_text(b.children))
            if getattr(b,'numbered',False) and getattr(b,'number_str',None):
                tmpl=book.options.get_str('rendering.chapter.template')
                return tmpl.replace('{{number}}',b.number_str).replace('{{chapter_title}}',plain)
            return plain
    return ''

def render_header_footer(book,renderer):
    # Render footer first, then header (para counter order)
    opts=book.options
    footer_html=''
    header_html=''
    if opts.is_present('html.footer') and opts.get('html.footer') is not None:
        md=opts.get_str('html.footer')
        parser=MdParser(superscript=opts.get_bool('crowbook.markdown.superscript',False),html_as_text=opts.get_bool('crowbook.html_as_text',True))
        blocks=parser.parse(md)
        # Clean like chapter: use book cleaner private
        book._clean_blocks(blocks)
        rendered=renderer.render_blocks(blocks)
        footer_html=f'<footer id = "footer">{rendered}</footer>\n'
    if opts.is_present('html.header') and opts.get('html.header') is not None:
        md=opts.get_str('html.header')
        parser=MdParser(superscript=opts.get_bool('crowbook.markdown.superscript',False),html_as_text=opts.get_bool('crowbook.html_as_text',True))
        blocks=parser.parse(md)
        book._clean_blocks(blocks)
        rendered=renderer.render_blocks(blocks)
        header_html=f'<div id = "top">{rendered}</div>\n'
    return header_html,footer_html

def render_inline_toc(book,renderer,roots,href_fn):
    # name handled as a template rendering with loc_toc, then ... output name raw
    name_opt=book.options.get_str('rendering.inline_toc.name','{{loc_toc}}')
    lang=book.options.get_str('lang','en')
    try:
        name=render_template(name_opt,{'loc_toc':locmod.loc_book(lang,'toc')})
    except Exception:
        name=name_opt
    toc_str=render_toc_list(renderer,roots,href_fn,indent=4)
    return f'<div id = "toc">\n  <h1>{name}</h1>\n  {toc_str}</div>\n'

def render_html_standalone(book):
    opts=book.options
    LOG.debug("Attempting to generate html...",target="crowbook::book")
    renderer=HtmlRenderer(book,mode='standalone')
    # Content first (para counters, images)
    roots=build_toc(book)
    has_toc=len(roots)>1
    href_fn=lambda node: f"#link-{node.link_id}"
    # Debug toc rendered elems in verbose: epub_builder::toc rendered elem for each root (?) Observed for html with 2 chapters it logged each root leaf. We'll log for roots recursively leaf elements as generated later, not crucial.
    content_parts=[]
    if opts.get_bool('rendering.inline_toc',False):
        content_parts.append(render_inline_toc(book,renderer,roots,href_fn))
    one_chapter=opts.get_bool('html.standalone.one_chapter',False)
    # chapter titles need rendering titles (inline rendering does not consume para), compute after contents to avoid link warnings order? It will re-render inlines causing duplicate resource warnings for links in headings in TOC and controls. Reference TOC generation likely happens before/after content and may duplicate warnings for heading links (rare). Accept.
    rendered_elems=[]
    for idx,elem in enumerate(book.elements):
        c=renderer.render_element_content(elem,idx)
        rendered_elems.append(c)
    # Build content with controls
    content_parts_elem=[]
    titles=[]
    if one_chapter:
        for elem in book.elements:
            titles.append(chapter_title_for_element(book,renderer,elem))
    for idx,c in enumerate(rendered_elems):
        content_parts_elem.append(f'<div id = "chapter-{idx}" class = "chapter">\n  {c}\n</div>')
        if one_chapter and idx < len(rendered_elems)-1:
            next_title=titles[idx+1]; prev_title=titles[idx]
            content_parts_elem.append(f'<p onclick = "javascript:showChapter({idx+1})" class = "chapterControls next_chapter chapter-{idx}">\n  <a href = "#chapter-{idx+1}">\n  {next_title} »\n  </a>\n</p>')
            content_parts_elem.append(f'<p onclick = "javascript:showChapter({idx})" class = "chapterControls prev_chapter chapter-{idx+1}">\n  <a href = "#chapter-{idx}">\n  « {prev_title}\n  </a>\n</p>')
    content=''.join(content_parts)+''.join(content_parts_elem)
    # toc string for template (rendered after contents? It uses renderer for titles; para unaffected)
    toc_str=''
    if True:
        # Always generate toc var (even if has_toc false template doesn't use). But generating can emit resource warnings duplicate for heading links. Reference probably generates TOC before content for verbose debug logs; logs order in verbose Attempting then epub_builder toc.
        toc_str=render_toc_list(renderer,roots,href_fn,indent=4) if roots else ''
        # verbose debug rendered elem for each toc item (epub_builder): approximate logging root leaves
        # Only log in verbose mode: LOG.debug will be suppressed otherwise.
        def log_toc(nodes):
            for n in nodes:
                if not n.children:
                    title=toc_title_html(renderer,n)
                    LOG.debug(f'rendered elem: "<li><a href=\\"#link-{n.link_id}\\">{title}</a></li>"',target="epub_builder::toc")
                else:
                    log_toc(n.children)
        # To avoid duplicate inline rendering resource warnings in non-verbose, only if LOG.verbose
        if LOG.verbose:
            log_toc(roots)
    header_html,footer_html=render_header_footer(book,renderer)
    # CSS/scripts/templates
    style=build_css(book,'html.css','html.css.add','html.css.colors',renderer)
    print_style=render_tmpl_or_error(get_template(book,'html.css.print'),{'lang':opts.get_str('lang','en')})
    script=build_script(book,renderer)
    # favicon
    favicon=''
    if opts.is_present('html.icon') and opts.get('html.icon') is not None:
        icon_val=opts.get_str('html.icon')
        # Resolve as image relative book parent/resource files. Missing gives image error with ./ candidate.
        # Use ResourceHandler resolving with source None gives ./icon ; correct only if book in cwd root. For subdir books, images base should include parent- use add_image_file.
        src=renderer.resources.add_image_file(icon_val)
        favicon=f'<link rel = "icon" href = "{src}">'
    highlight_code=(renderer.highlight=='highlight.js')
    highlight_css=''; highlight_js=''
    if highlight_code:
        highlight_css=render_tmpl_or_error(get_template(book,'html.highlight.css'),{'lang':opts.get_str('lang','en')})
        js_bytes=None
        if opts.is_present('html.highlight.js') and opts.get('html.highlight.js') is not None:
            tmpl_text=get_template(book,'html.highlight.js'); js_bytes=tmpl_text.encode('utf-8')
        else:
            js_bytes=load_bytes('templates/html.highlight.js')
        highlight_js='data:text/javascript;base64,'+b64_nopad(js_bytes)
    lang=opts.get_str('lang','en')
    # Metadata rendered with this renderer: use book.metadata_inlines but render with renderer to handle links/images etc. Those are new inline nodes; plain from book methods separately.
    def meta_html(key):
        return renderer.render_inlines(book.metadata_inlines(key))
    def meta_plain(key):
        return book.metadata_plain(key)
    has_subtitle=opts.is_present('subtitle') and opts.get('subtitle') is not None
    has_autograph=opts.is_present('autograph') and opts.get('autograph') is not None and str(opts.get('autograph')).strip()!=''
    template=get_template(book,'html.standalone.template')
    ctx={
        'lang':lang,
        'author_raw':meta_plain('author'),
        'favicon':favicon,
        'title_raw':meta_plain('title'),
        'style':style,
        'print_style':print_style,
        'highlight_code':highlight_code,
        'highlight_css':highlight_css,
        'highlight_js':highlight_js,
        'script':script,
        'json_data':json_data(book),
        'has_toc':has_toc,
        'one_chapter':one_chapter,
        'loc_display_all':locmod.loc_book(lang,'display_all'),
        'loc_display_one':locmod.loc_book(lang,'display_one'),
        'book_svg':svg_data_uri('book.svg'),
        'pages_svg':svg_data_uri('pages.svg'),
        'menu_svg':svg_data_uri('menu.svg'),
        'loc_toc':locmod.loc_book(lang,'toc'),
        'title':meta_html('title'),
        'toc':toc_str,
        'header':header_html,
        'footer':footer_html,
        'author':meta_html('author'),
        'has_subtitle':has_subtitle,
        'subtitle':meta_html('subtitle') if has_subtitle else '',
        'has_autograph':has_autograph,
        'autograph':meta_html('autograph') if has_autograph else '',
        'content':content,
    }
    return render_tmpl_or_error(template,ctx)
