def write_stdout_bytes(data):
    if isinstance(data,str): data=data.encode('utf-8')
    try:
        sys.stdout.buffer.write(data); sys.stdout.buffer.flush()
    except BrokenPipeError:
        pass

def write_stdout_text(s):
    write_stdout_bytes(s)

def panic_exit(e):
    thread=getattr(e,'thread','main')
    sys.stderr.write(f"\nthread '{thread}' ({os.getpid()}) panicked at {e.location}:\n{e.msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    return 101

def prompt_autograph():
    write_stdout_text("Enter autograph:\n")
    try:
        data=sys.stdin.buffer.read()
    except Exception:
        data=b''
    try:
        return data.decode('utf-8')
    except Exception:
        return data.decode('utf-8','replace')

def make_logger(args,runtime_lang):
    # stats overrides fancy/verbose format to simple
    if args.stats:
        lg=CrowLogger(verbose=False,quiet=args.quiet,no_fancy=True,force_emoji=args.force_emoji,runtime_lang=runtime_lang)
    else:
        lg=CrowLogger(verbose=args.verbose,quiet=args.quiet,no_fancy=args.no_fancy,force_emoji=args.force_emoji,runtime_lang=runtime_lang)
    set_logger(lg)
    # logger module global LOG used by modules imported as `from logger import LOG` - they captured object at import time.
    # Mutate/replace attributes of that original object as well by assigning logger_mod.LOG fields? Our modules do `from logger import LOG` then call LOG.xxx; that reference is to original CrowLogger instance created at logger import.
    # To ensure all see same, copy state into original object.
    orig=logger_mod.LOG
    orig.__dict__.update(lg.__dict__)
    # set_logger set logger_mod.LOG to lg, but imported references still orig. Make both point: set logger_mod.LOG=orig with updated dict
    logger_mod.LOG=orig
    return orig

def stats_text(book):
    # collect file elements
    rows=[]
    for elem in book.elements:
        if elem.kind!='file': continue
        text=collect_stats_text(elem)
        chars=len(text); words=len(text.split())
        rows.append((elem.filename,chars,words))
    if not rows:
        raise PanicError("src/lib/stats.rs:285:14","called `Option::unwrap()` on a `None` value")
    maxlen=max(len(r[0]) for r in rows)
    width=maxlen+6
    def fmt(name,chars,words):
        ratio=(chars/words) if words else float('nan')
        ratio_str=f"{ratio:.2f}" if words else "NaN"
        return f"{name:<{width}} {chars:>5} {words:>10} {ratio_str:>11}"
    out=[]
    out.append(f"{'Chapter':<{width}} {'Chars':>5} {'Words':>10} {'Chars/Word':>11}\n")
    out.append("---------\n")
    total_c=0; total_w=0
    for name,c,w in rows:
        out.append(fmt(name,c,w)+"\n"); total_c+=c; total_w+=w
    out.append("---------\n")
    out.append(fmt("TOTAL:",total_c,total_w)+"\n")
    out.append("\n")
    return ''.join(out)

def collect_stats_text(elem):
    parts=[]
    def walk_inls(inls):
        for n in inls:
            if n.kind=='text': parts.append(n.text)
            elif n.kind=='code': parts.append(n.text)
            elif n.kind=='softbreak': parts.append(' ')
            elif n.kind=='hardbreak': parts.append('\n')
            elif n.kind=='html': parts.append(n.text)
            elif n.children: walk_inls(n.children)
    def walk_blocks(blks):
        for b in blks:
            if b.kind in ('para','heading'):
                walk_inls(b.children)
            elif b.kind=='codeblock':
                parts.append(b.text)
            elif b.kind=='blockquote': walk_blocks(b.children)
            elif b.kind=='list':
                for it in b.children: walk_blocks(it.children)
            elif b.kind=='table':
                for h in b.headers: walk_inls(h)
                for row in b.rows:
                    for c in row: walk_inls(c)
            elif b.kind=='deflist':
                for term,defs in b.items:
                    walk_inls(term)
                    for d in defs: walk_blocks(d)
            elif b.kind=='htmlblock':
                parts.append(b.text)
    walk_blocks(elem.blocks)
    for label in elem.footnote_order:
        walk_blocks(elem.footnotes.get(label,[]))
    return ''.join(parts)

def success_msg(fmt,display):
    names={'html':'HTML (standalone page)','html.dir':'HTML (multiple pages)','epub':'EPUB','tex':'LaTeX','pdf':'PDF'}
    base=f"Succesfully generated {names.get(fmt,fmt.upper())}"
    if display:
        return f"{base}: {display}"
    return base

def display_for_dest(dest):
    # dest is a filesystem path string (relative to cwd or absolute); display relative to cwd normalized
    try:
