import os, sys
from logger import LOG
from errors import CrowError
from book import PanicError
import renderers

def success_msg(fmt,display):
    names={'html':'HTML (standalone page)','html.dir':'HTML (multiple pages)','epub':'EPUB','tex':'LaTeX','pdf':'PDF'}
    base=f"Succesfully generated {names.get(fmt,fmt.upper())}"
    return f"{base}: {display}" if display else base

def display_for_dest(dest):
    try:
        return os.path.relpath(os.path.abspath(dest), os.getcwd())
    except Exception:
        return str(dest)

def write_output_file(dest_path,data,display_for_error):
    if isinstance(data,str): data=data.encode('utf-8')
    try:
        with open(dest_path,'wb') as f: f.write(data)
    except FileNotFoundError:
        raise CrowError(f"could not create file '{display_for_error}': 'No such file or directory (os error 2)")
    except IsADirectoryError:
        raise CrowError(f"could not create file '{display_for_error}': 'Is a directory (os error 21)")
    except OSError as e:
        raise CrowError(f"could not create file '{display_for_error}': '{e.strerror} (os error {e.errno})")

def dest_for_format(book,fmt):
    opts=book.options
    key={'html':'output.html','epub':'output.epub','tex':'output.tex','pdf':'output.pdf','html.dir':'output.html.dir','odt':'output.odt'}[fmt]
    if not opts.is_present(key) or opts.get(key) is None:
        return None
    raw=str(opts.get(key))
    is_auto=False
    if raw=='auto':
        is_auto=True
        stem=book.filename_for_output or 'output'
        ext={'html':'html','epub':'epub','tex':'tex','pdf':'pdf','odt':'odt'}.get(fmt)
        if fmt=='html.dir':
            # reference bug: destination passed/logged is output_html, actual dir is auto
            return ('output_html','auto',True)
        raw=f"{stem}.{ext}"
    base_path=opts.get_str('output.base_path','') if opts.is_present('output.base_path') and opts.get('output.base_path') is not None else ''
    cand=raw
    if base_path:
        cand=os.path.join(base_path,cand) if not os.path.isabs(cand) else cand
    if book.parent_display and not os.path.isabs(cand):
        cand=os.path.join(book.parent_display,cand)
    return (cand,cand,is_auto)

def do_render(book,fmt):
    if fmt=='html':
        return renderers.render_html_standalone(book)
    elif fmt=='tex':
        return renderers.render_tex(book)
    elif fmt=='epub':
        return renderers.render_epub(book)
    elif fmt=='pdf':
        return renderers.render_pdf(book)
    elif fmt=='html.dir':
        raise CrowError("internal: html.dir handled separately")
    elif fmt=='odt':
        raise CrowError("unknown format odt")
    else:
        raise CrowError(f"unknown format {fmt}")

def render_to(book,fmt,output,LOG):
    if fmt=='odt':
        LOG.fancy_error("unknown format odt"); return
    # dest determination
    if output is not None:
        if output=='-':
            dest=None; dest_display=None; actual=None; is_auto=False
        else:
            dest=output; actual=output; dest_display=display_for_dest(output); is_auto=False
    else:
        d=dest_for_format(book,fmt)
        if d is None:
            dest=None; actual=None; dest_display=None; is_auto=False
        else:
            dest,actual,is_auto=d; dest_display=display_for_dest(dest)
    try:
        if fmt=='html.dir':
            if dest is None:
                raise CrowError("Error during rendering: can only render HTML directory to a path, not to a stream")
            # Special panic / actual path logic in renderer
            renderers.render_html_dir(book,actual,requested_dest=dest)
            LOG.info(success_msg(fmt,dest_display))
            return
        data=do_render(book,fmt)
        if dest is None:
            # stdout
            if isinstance(data,str): sys.stdout.buffer.write(data.encode('utf-8'))
            else: sys.stdout.buffer.write(data)
            sys.stdout.buffer.flush()
            LOG.info(success_msg(fmt,None))
        else:
            write_output_file(actual,data,output if output is not None else actual)
            LOG.info(success_msg(fmt,dest_display))
    except CrowError as e:
        LOG.fancy_error(e.msg)
        return

def render_all(book,LOG):
    fmts=[]
    for fmt in ['tex','html','html.dir','pdf','epub','odt']:
        d=dest_for_format(book,fmt)
        if d is not None:
            fmts.append((fmt,d))
    # Pre-warn for epub zip if any epub, to mimic parallel warning position approximately - render_epub itself will warn; to avoid duplicate, we let epub renderer warn when called.
    for fmt,d in fmts:
        if fmt=='odt':
            continue
        dest,actual,is_auto=d
        display=display_for_dest(dest)
        try:
            if fmt=='html.dir':
                renderers.render_html_dir(book,actual,requested_dest=dest)
            else:
                data=do_render(book,fmt)
                write_output_file(actual,data,actual)
            LOG.info(success_msg(fmt,display))
        except CrowError as e:
            LOG.error(f"Error rendering {fmt}: {e.msg}")
