def tex_escape(s,book,for_code=False):
    escape_nb=book.options.get_bool('tex.escape_nb_spaces',True)
    out=[]
    for ch in str(s):
        if escape_nb and ch=='\u202f':
            out.append('\\,'); continue
        if escape_nb and ch=='\u00a0':
            out.append('~'); continue
        if escape_nb and ch=='\u2002':
            out.append('\\enspace '); continue
        if for_code and ch==' ':
            out.append('\\hphantom{ }\\allowbreak{}'); continue
        if ch=='&': out.append('\\&')
        elif ch=='%': out.append('\\%')
        elif ch=='$': out.append('\\$')
        elif ch=='#': out.append('\\#')
        elif ch=='_': out.append('\\_\\allowbreak{}' if for_code else '\\_')
        elif ch=='{': out.append('\\{')
        elif ch=='}': out.append('\\}')
        elif ch=='~': out.append('\\textasciitilde{}')
        elif ch=='^': out.append('\\textasciicircum{}')
        elif ch=='\\': out.append('\\textbackslash{}')
        elif ch=='<': out.append('\\textless{}')
        elif ch=='>': out.append('\\textgreater{}')
        elif ch=='!' and not for_code: out.append('!{}')
        else:
            out.append(ch)
            if for_code and ch in '/.:,;()[]':
