            # If a setcounter is pending but para before heading? Reference label comes before para, setcounter likely before heading later; keep setcounter_before for heading.
            prefix+=f"\\label{{chapter-{index}}}\n"
            self.first_heading_done=False  # heading later should NOT get label again - but our heading code uses first_heading_done to decide label; set to True to suppress? Yet setcounter needs happen before heading: heading code only applies pre if is_first. We need separate flag.
            self.first_heading_done=True
            self._label_already=True
        else:
            self._label_already=False
        # monkey adjust heading label: if label already, heading should not emit label but should emit setcounter. Our _render_heading checks not first_heading_done (False now if prefix). Fix by introducing flag in heading rendering handled below via attribute.
        content=self.render_blocks(elem.blocks)
        if self.current_footnotes:
            for label in list(self.current_footnotes):
                fb=elem.footnotes.get(label,[])
                content+=f"\\footnotetext[{label}]{{{self.render_blocks(fb)}}}"
        return prefix+content, after_counter
