        cmd=self._heading_command(0)
        if elem.title_inlines is not None:
            title=self.render_inlines(elem.title_inlines)
        elif elem.title_blocks:
            title=self.render_blocks(elem.title_blocks)
        else:
            title=''
        reset=self.book.options.get_bool('rendering.part.reset_counter',True)
        pre="\\setcounter{chapter}{0}" if reset else ""
        return f"{pre}\\{cmd}{{{title}}}\n\\label{{chapter-{index}}}\n"

# Patch heading label suppression: need modify _render_heading to respect _label_already for setcounter. We'll monkey? Instead adjust logic in class above is not present; handled by alternative: in render_file_content, if label already, first_heading_done=True means heading won't get setcounter. To support explicit+para-before-heading (rare), we accept.

def render_tex(book):
    opts=book.options
    LOG.debug("Attempting to generate tex...",target="crowbook::book")
    renderer=TexRenderer(book)
    # content
    content_parts=[]; chapter_counter=0
    for idx,elem in enumerate(book.elements):
        if elem.kind=='part':
            if opts.get_bool('rendering.part.reset_counter',True): chapter_counter=0
            content_parts.append(renderer.render_part(elem,idx))
        else:
            c,chapter_counter=renderer.render_file_content(elem,idx,chapter_counter)
            content_parts.append(c)
    content=''.join(content_parts)
    # cover after content (image numbering)
    use_cover=False; cover_path=''
    if opts.get_bool('tex.cover',False) and opts.is_present('cover') and opts.get('cover') is not None:
        use_cover=True; cover_path=renderer.resources.add_cover(opts.get_str('cover'))
    # flags for template
    def any_node(pred):
        found=False
        def walk_b(blks):
            nonlocal found
            for b in blks:
                if pred(b): found=True
                if b.kind=='blockquote': walk_b(b.children)
                elif b.kind=='list':
                    for it in b.children: walk_b(it.children)
                elif b.kind=='deflist':
                    for _,defs in b.items:
                        for d in defs: walk_b(d)
        def walk_i(inls):
            nonlocal found
            for n in inls:
                if pred(n): found=True
                if n.children: walk_i(n.children)
        for e in book.elements:
            if e.kind=='file':
                # walk blocks and inlines
                def wb(blks):
                    for b in blks:
                        if pred(b): 
                            nonlocal_found=True
                        if b.kind in ('para','heading'): walk_i(b.children)
                        elif b.kind=='blockquote': wb(b.children)
                        elif b.kind=='list':
                            for it in b.children: wb(it.children)
                        elif b.kind=='table':
                            for h in b.headers: walk_i(h)
                            for row in b.rows:
                                for c in row: walk_i(c)
                        elif b.kind=='deflist':
                            for term,defs in b.items:
                                walk_i(term)
                                for d in defs: wb(d)
                # simpler use walk_b and also check block kinds (pred receives blocks)
                walk_b(e.blocks)
                # inline check via traverse again
                def wi(blks):
                    for b in blks:
                        if b.kind in ('para','heading'): walk_i(b.children)
                        elif b.kind=='blockquote': wi(b.children)
                        elif b.kind=='list':
                            for it in b.children: wi(it.children)
                        elif b.kind=='table':
                            for h in b.headers: walk_i(h)
                            for row in b.rows:
                                for c in row: walk_i(c)
                wi(e.blocks)
        return found
    use_strikethrough=any_node(lambda n: getattr(n,'kind',None)=='strike')
    use_task=False
    def check_task(blks):
        nonlocal use_task
        for b in blks:
            if b.kind=='list':
                for it in b.children:
                    if it.task is not None: use_task=True
                    check_task(it.children)
            elif b.kind=='blockquote': check_task(b.children)
    for e in book.elements:
        if e.kind=='file': check_task(e.blocks)
    from htmlrender import book_uses_codeblocks
    use_codeblocks=book_uses_codeblocks(book)
    use_images=any_node(lambda n: getattr(n,'kind',None)=='image')
    use_tables=any_node(lambda n: getattr(n,'kind',None)=='table')
    cls=opts.get_str('tex.class','book')
    margin_left=opts.get_str('tex.margin.left') if opts.is_present('tex.margin.left') and opts.get('tex.margin.left') is not None else ('2.5cm' if cls=='book' else '2cm')
    margin_right=opts.get_str('tex.margin.right') if opts.is_present('tex.margin.right') and opts.get('tex.margin.right') is not None else ('1.5cm' if cls=='book' else '2cm')
    def meta_tex(key):
        return renderer.render_inlines(book.metadata_inlines(key))
    has_tex_size=opts.is_present('tex.font.size') and opts.get('tex.font.size') is not None
    ctx={
        'has_tex_size':has_tex_size,
        'tex_size':str(opts.get_int('tex.font.size',0)) if has_tex_size else '',
        'class':cls,
        'xelatex':opts.get_str('tex.command','xelatex')=='xelatex',
        'tex_lang':locmod.tex_lang_name(opts.get_str('lang','en')),
        'use_strikethrough':use_strikethrough,
        'use_taskitem':use_task,
        'author':meta_tex('author'),
        'title':meta_tex('title'),
        'description':meta_tex('description') if opts.is_present('description') and opts.get('description') is not None else '',
        'initials':opts.get_bool('rendering.initials',False),
        'stdpage':opts.get_bool('tex.stdpage',False),
        'papersize':opts.get_str('tex.paper.size','a5paper'),
        'margin_top':opts.get_str('tex.margin.top','2cm'),
        'margin_bottom':opts.get_str('tex.margin.bottom','1.5cm'),
        'margin_left':margin_left,
        'margin_right':margin_right,
        'use_cover':use_cover,
        'cover_path':cover_path,
        'date':meta_tex('date') if opts.is_present('date') and opts.get('date') is not None else '',
        'book':cls=='book',
