        'has_autograph':opts.is_present('autograph') and opts.get('autograph') is not None and str(opts.get('autograph')).strip()!='',
        'autograph':meta_tex('autograph') if opts.is_present('autograph') and opts.get('autograph') is not None else '',
        'has_date':opts.is_present('date') and opts.get('date') is not None,
        'has_version':opts.is_present('version') and opts.get('version') is not None,
        'version':meta_tex('version') if opts.is_present('version') and opts.get('version') is not None else '',
        'has_author':opts.get_str('author','')!='',
        'has_license':opts.is_present('license') and opts.get('license') is not None,
        'license':meta_tex('license') if opts.is_present('license') and opts.get('license') is not None else '',
        'use_codeblocks':use_codeblocks,
        'use_images':use_images,
        'use_tables':use_tables,
        'additional_code':opts.get_str('tex.template.add','') if opts.is_present('tex.template.add') and opts.get('tex.template.add') is not None else '',
        'chapter_name':opts.get_str('rendering.chapter','') if opts.is_present('rendering.chapter') and opts.get('rendering.chapter') is not None else '',
        'part_name':opts.get_str('rendering.part','') if opts.is_present('rendering.part') and opts.get('rendering.part') is not None else '',
        'tex_title':opts.get_bool('tex.title',True),
        'inline_toc':opts.get_bool('rendering.inline_toc',False),
        'content':content,
        'lang':opts.get_str('lang','en'),
