def render_pdf(book):
    opts=book.options
    LOG.debug("Attempting to generate pdf...",target="crowbook::book")
    tex_text=render_tex(book)
    renderer=getattr(render_tex,'_last_renderer',None)
    import tempfile, subprocess, shutil
    base=opts.get_str('crowbook.temp_dir','') if opts.is_present('crowbook.temp_dir') and opts.get('crowbook.temp_dir') is not None else ''
    parent=None
    if base:
        parent=os.path.join(book.parent_display,base) if book.parent_display and not os.path.isabs(base) else base
    tmpdir=tempfile.mkdtemp(dir=parent)
    try:
        with open(os.path.join(tmpdir,'result.tex'),'w',encoding='utf-8',newline='\n') as f: f.write(tex_text)
        if renderer is not None:
            for arc,cand,data in renderer.resources.images:
                dest=os.path.join(tmpdir,arc); os.makedirs(os.path.dirname(dest),exist_ok=True)
                with open(dest,'wb') as f: f.write(data)
        resource_files=opts.get('resources.files') if isinstance(opts.get('resources.files'),list) else []
        if resource_files:
            out_path=opts.get_str('resources.out_path','data')
            for rf in resource_files:
                cand=os.path.join(book.parent_display,str(rf)) if book.parent_display else str(rf)
                if os.path.exists(cand):
                    dest=os.path.join(tmpdir,out_path,os.path.basename(str(rf))); os.makedirs(os.path.dirname(dest),exist_ok=True)
                    with open(cand,'rb') as src, open(dest,'wb') as dst: dst.write(src.read())
        cmd=opts.get_str('tex.command','xelatex')
        for _ in range(3):
            try:
                cp=subprocess.run([cmd,'result.tex'],cwd=tmpdir,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=120)
            except OSError:
                raise CrowError(f"Error during temporary files editing: failed to run command '{cmd}'")
            if cp.returncode!=0:
                raise CrowError(f"Error during temporary files editing: {cmd} didn't return succesfully")
        try:
            with open(os.path.join(tmpdir,'result.pdf'),'rb') as f: data=f.read()
        except OSError:
            raise CrowError(f"Error during temporary files editing: could not open result of command '{cmd}'")
        return data
    finally:
        try: shutil.rmtree(tmpdir)
        except Exception: pass
